//  手計算での検算なしに正確性を保証できる設計になっている。ほぼ全問に途中式付き)
window.NTT_Q_MATH = [
  { id: "ntt_math_0001", subject: "math", category: "連立方程式", level: 2, type: "input", question: "連立方程式 4x + 3y = 54, 2x + 1y = 22 を解いたとき、xの値を求めなさい。", answer: "6", steps: ["1つ目の式×1: 4x + 3y = 54", "2つ目の式×3: 6x + 3y = 66", "辺々を引くとyが消える: -2x = -12", "x = -12 ÷ -2 = 6"], explanation: "連立方程式は「加減法」で解くことができます。yの係数をそろえてから2つの式を引き算すると、yが消えてxだけの式になります。1つ目の式を1倍、2つ目の式を3倍すると、どちらもyの係数が3になるので、引き算でyを消去できます。" },
  { id: "ntt_math_0002", subject: "math", category: "割合", level: 1, type: "choice", question: "160人の30%は何人ですか?", choices: ["48人", "53人", "43人", "96人"], answer: "48人", steps: ["30% = 30/100", "160 × 30 ÷ 100 = 48"], explanation: "「○%」は「100人あたり○人の割合」という意味なので、割合を計算するときは百分率を100で割って小数(または分数)に直してからかけます。30%=30/100なので、160×30/100=48人になります。" },
  { id: "ntt_math_0003", subject: "math", category: "正負の数", level: 1, type: "input", question: "(-13) + (-3) を計算しなさい。", answer: "-16", steps: ["(-13) + (-3) = -16"], explanation: "正負の数のたし算では、符号が同じ数どうしは絶対値を足して同じ符号をつけ、符号が異なる数どうしは絶対値の差をとって絶対値の大きい方の符号をつけます。(-13)+(-3)=-16になります。" },
  { id: "ntt_math_0004", subject: "math", category: "単位換算", level: 1, type: "input", question: "5.1kmは何mですか?", answer: "5100m", steps: ["1km = 1000m", "5.1 × 1000 = 5100", "よって 5100m"], explanation: "単位を換算するときは、まず1kmが何mにあたるかを確認します。1km=1000mなので、5.1kmはその5.1倍で5100mになります。" },
  { id: "ntt_math_0005", subject: "math", category: "正負の数", level: 1, type: "input", question: "(-15) - (4) を計算しなさい。", answer: "-19", steps: ["(-15) - (4) = (-15) + (-4)", "= -19"], explanation: "正負の数のひき算は、引く数の符号を反対にしてたし算に直すと考えやすくなります。(-15)-(4)=(-15)+(-4)=-19になります。" },
  { id: "ntt_math_0006", subject: "math", category: "鶴亀算", level: 5, type: "input", question: "鶴と亀が合わせて29匹おり、足の合計本数は86本である。鶴は何匹いますか?", answer: "15匹", steps: ["全部鶴と仮定: 29 × 2 = 58本", "実際との差: 86 - 58 = 28本", "亀の数: 28 ÷ 2 = 14匹", "鶴の数: 29 - 14 = 15匹"], explanation: "鶴亀算の定番の解き方は「全部鶴だったと仮定する」ことです。全部鶴なら足の合計は29×2=58本になるはずですが、実際は86本なのでその差は亀が混じっている分です。亀1匹につき鶴より足が2本多いので、差を2で割ると亀の数が分かります。" },
  { id: "ntt_math_0007", subject: "math", category: "四則演算", level: 1, type: "input", question: "10 + 2 × 12 を計算しなさい。", answer: "34", steps: ["2 × 12 = 24", "10 + 24 = 34"], explanation: "計算の順序のルールとして、かけ算・わり算はたし算・ひき算より先に計算します。まず2×12を計算してから10を足します。" },
  { id: "ntt_math_0008", subject: "math", category: "単位換算", level: 1, type: "input", question: "17.3Lは何mLですか?", answer: "17300mL", steps: ["1L = 1000mL", "17.3 × 1000 = 17300", "よって 17300mL"], explanation: "単位を換算するときは、まず1Lが何mLにあたるかを確認します。1L=1000mLなので、17.3Lはその17.3倍で17300mLになります。" },
  { id: "ntt_math_0009", subject: "math", category: "図形と計量", level: 4, type: "choice", question: "sin90° の値を求めなさい。", choices: ["1", "0", "1/2", "√2/2"], answer: "1", explanation: "sin90°=1という三角比の基本値です。90°では単位円上の点のy座標が最大の1になります。" },
  { id: "ntt_math_0010", subject: "math", category: "図形と計量", level: 4, type: "choice", question: "cos30° の値を求めなさい。", choices: ["√3/2", "0", "1", "1/2"], answer: "√3/2", explanation: "cos30°=√3/2という三角比の基本値です。30°-60°-90°の直角三角形の辺の比から求められます。cos30°はsin60°と同じ値になります。" },
  { id: "ntt_math_0011", subject: "math", category: "確率", level: 3, type: "input", question: "サイコロを1回振って、1以下の目が出る確率を求めなさい。", answer: "1/6", steps: ["1以下の目: 1(1通り)", "全体は6通り", "確率 = 1/6 = 1/6"], explanation: "確率は「求める場合の数÷すべての場合の数」で計算します。サイコロの目の出方は全部で6通りあり、そのうち1以下の目は1通りあります。" },
  { id: "ntt_math_0012", subject: "math", category: "場合の数", level: 4, type: "input", question: "異なる5個から2個を選ぶ方法(組み合わせ)は何通りありますか?", answer: "10通り", steps: ["5!/(2!×3!) を計算する", "= 10通り"], explanation: "順序を区別しない「組み合わせ」は、まず順列(並べる場合の数)を求めてから、選んだ2個を並べ替える2!通りで割ることで求められます。" },
  { id: "ntt_math_0013", subject: "math", category: "図形", level: 3, type: "input", question: "縦10cm、横4cm、高さ4cmの直方体の体積を求めなさい。", answer: "160cm³", steps: ["体積 = 縦 × 横 × 高さ", "10 × 4 × 4 = 160"], explanation: "直方体の体積は「縦×横×高さ」で求めます。底面積(縦×横)に高さをかけると考えることもできます。" },
  { id: "ntt_math_0014", subject: "math", category: "鶴亀算", level: 5, type: "input", question: "鶴と亀が合わせて31匹おり、足の合計本数は112本である。鶴は何匹いますか?", answer: "6匹", steps: ["全部鶴と仮定: 31 × 2 = 62本", "実際との差: 112 - 62 = 50本", "亀の数: 50 ÷ 2 = 25匹", "鶴の数: 31 - 25 = 6匹"], explanation: "鶴亀算の定番の解き方は「全部鶴だったと仮定する」ことです。全部鶴なら足の合計は31×2=62本になるはずですが、実際は112本なのでその差は亀が混じっている分です。亀1匹につき鶴より足が2本多いので、差を2で割ると亀の数が分かります。" },
  { id: "ntt_math_0015", subject: "math", category: "図形と計量", level: 4, type: "choice", question: "sin0° の値を求めなさい。", choices: ["0", "1", "1/2", "√2/2"], answer: "0", explanation: "sin0°=0という三角比の基本値です。0°では単位円上の点のy座標が0になります。" },
  { id: "ntt_math_0016", subject: "math", category: "図形", level: 3, type: "input", question: "直角三角形の直角をはさむ2辺の長さが5cmと12cmのとき、斜辺の長さを求めなさい。", answer: "13cm", steps: ["5² + 12² = 25 + 144 = 169", "√169 = 13"], explanation: "直角三角形では「(斜辺)²=(辺1)²+(辺2)²」という三平方の定理(ピタゴラスの定理)が成り立ちます。2辺の2乗の和を求めてから平方根をとると斜辺の長さが分かります。" },
  { id: "ntt_math_0017", subject: "math", category: "整数", level: 1, type: "input", question: "38と36の最小公倍数を求めなさい。", answer: "684", steps: ["38と36の最大公約数は2", "38 × 36 ÷ 2 = 684"], explanation: "最小公倍数とは、2つの数のどちらの倍数にもなっている整数のうち、最も小さいものです。最大公約数を使うと (最小公倍数)=(38×36)÷(最大公約数) で求められます。" },
  { id: "ntt_math_0018", subject: "math", category: "平方根", level: 3, type: "input", question: "√196 の値を求めなさい。", answer: "14", steps: ["14 × 14 = 196", "よって √196 = 14"], explanation: "√196(ルート196)とは、2乗すると196になる正の数のことです。14を2乗すると14×14=196になるので、√196=14です。" },
  { id: "ntt_math_0019", subject: "math", category: "割合", level: 1, type: "choice", question: "35人の60%は何人ですか?", choices: ["21人", "26人", "16人", "42人"], answer: "21人", steps: ["60% = 60/100", "35 × 60 ÷ 100 = 21"], explanation: "「○%」は「100人あたり○人の割合」という意味なので、割合を計算するときは百分率を100で割って小数(または分数)に直してからかけます。60%=60/100なので、35×60/100=21人になります。" },
  { id: "ntt_math_0020", subject: "math", category: "平方根", level: 3, type: "input", question: "√12 を最も簡単な形(a√b)に変形したとき、根号の外に出る数(a)を求めなさい。", answer: "2", steps: ["12 を素因数分解して 2² × 3 の形にする", "√(2² × 3) = 2√3"], explanation: "根号の中に同じ数の2乗の形(平方数)が含まれているとき、その数は根号の外に出すことができます。12=2²×3と分解できるので、2²の部分が根号の外に出て2√3になります。" },
  { id: "ntt_math_0021", subject: "math", category: "連立方程式", level: 2, type: "input", question: "連立方程式 5x + 1y = 34, 4x + 1y = 29 を解いたとき、xの値を求めなさい。", answer: "5", steps: ["1つ目の式×1: 5x + 1y = 34", "2つ目の式×1: 4x + 1y = 29", "辺々を引くとyが消える: 1x = 5", "x = 5 ÷ 1 = 5"], explanation: "連立方程式は「加減法」で解くことができます。yの係数をそろえてから2つの式を引き算すると、yが消えてxだけの式になります。1つ目の式を1倍、2つ目の式を1倍すると、どちらもyの係数が1になるので、引き算でyを消去できます。" },
  { id: "ntt_math_0022", subject: "math", category: "図形", level: 3, type: "input", question: "半径4cmの円の円周を求めなさい。円周率はπとすること。", answer: "8πcm", steps: ["直径 = 4 × 2 = 8", "円周 = 8 × π = 8π"], explanation: "円周は「直径×円周率」で求めます。直径は半径の2倍なので、まず直径を求めてからπをかけます。" },
  { id: "ntt_math_0023", subject: "math", category: "整数", level: 1, type: "input", question: "56と50の最大公約数を求めなさい。", answer: "2", steps: ["56を割り切れる数、50を割り切れる数をそれぞれ書き出す", "共通する約数のうち最大のものが2"], explanation: "最大公約数とは、2つの数を共に割り切ることができる整数のうち、最も大きいものです。56の約数と50の約数を比べると、共通する最大の約数は2です。" },
  { id: "ntt_math_0024", subject: "math", category: "小数", level: 1, type: "input", question: "5.7 × 6 を計算しなさい。", answer: "34.2", steps: ["5.7 × 6 = 34.2"], explanation: "小数×整数は、いったん小数点を無視して整数どうしのかけ算をしてから、あとで小数点の位置を戻すと計算しやすくなります。5.7×6=34.2になります。" },
  { id: "ntt_math_0025", subject: "math", category: "速さ・時間・距離", level: 2, type: "input", question: "66kmの道のりを2時間で進むと、時速は何kmですか?", answer: "時速33km", steps: ["速さ = 距離 ÷ 時間", "66 ÷ 2 = 33"], explanation: "「速さ=距離÷時間」という公式を使います。1時間あたりに進む距離を求めることになります。" },
  { id: "ntt_math_0026", subject: "math", category: "平均", level: 1, type: "input", question: "3個の数 86、32、26 の平均を求めなさい。", answer: "48", steps: ["86+32+26 = 144", "144 ÷ 3 = 48"], explanation: "平均とは、いくつかの数を均等にならしたときの値のことで、「合計÷個数」で求めます。まずすべての数を足し合わせ、その合計を個数で割ります。" },
  { id: "ntt_math_0027", subject: "math", category: "二次関数", level: 4, type: "choice", question: "y = x² - 6x + 13 の頂点の座標を求めなさい。", choices: ["(3, 4)", "(4, 4)", "(3, 5)", "(-3, 4)"], answer: "(3, 4)", steps: ["y = x² - 6x + 13 を平方完成する", "y = (x - (3))² + 4", "頂点は (3, 4)"], explanation: "二次関数の頂点を求めるには「平方完成」という変形を行い、y=(x-p)²+qの形にします。この形になれば、頂点の座標は(p, q)であるとすぐに分かります。" },
  { id: "ntt_math_0028", subject: "math", category: "確率", level: 3, type: "input", question: "サイコロを1回振って、3以下の目が出る確率を求めなさい。", answer: "1/2", steps: ["3以下の目: 1, 2, 3(3通り)", "全体は6通り", "確率 = 3/6 = 1/2"], explanation: "確率は「求める場合の数÷すべての場合の数」で計算します。サイコロの目の出方は全部で6通りあり、そのうち3以下の目は3通りあります。" },
  { id: "ntt_math_0029", subject: "math", category: "確率", level: 4, type: "input", question: "大小2つのサイコロを同時に振るとき、目の和が6になる確率を求めなさい。", answer: "5/36", steps: ["目の和が6になる組: (1,5)、(2,4)、(3,3)、(4,2)、(5,1)", "全体は6×6=36通り", "確率 = 5/36 = 5/36"], explanation: "大小2つのサイコロの目の出方は全部で6×6=36通りあります。そのうち目の和が6になる組み合わせを数え上げると5通りあります。" },
  { id: "ntt_math_0030", subject: "math", category: "仕事算", level: 5, type: "input", question: "ある作業をAさん1人で行うと6日、Bさん1人で行うと12日かかる。2人で一緒に行うと何日で終わりますか?", answer: "4日", steps: ["Aさんの1日の仕事量: 1/6、Bさんの1日の仕事量: 1/12", "2人合わせた1日の仕事量: 1/6 + 1/12 = 18/72", "かかる日数 = 1 ÷ (18/72) = 72/18 = 4日"], explanation: "仕事全体の量を1とすると、Aさんは1日に1/6、Bさんは1日に1/12の仕事をこなします。2人が一緒に働くと1日あたりの仕事量はその合計になるので、全体の1をその合計で割ると完成にかかる日数が求められます。" },
  { id: "ntt_math_0031", subject: "math", category: "平方根", level: 3, type: "input", question: "√75 を最も簡単な形(a√b)に変形したとき、根号の外に出る数(a)を求めなさい。", answer: "5", steps: ["75 を素因数分解して 5² × 3 の形にする", "√(5² × 3) = 5√3"], explanation: "根号の中に同じ数の2乗の形(平方数)が含まれているとき、その数は根号の外に出すことができます。75=5²×3と分解できるので、5²の部分が根号の外に出て5√3になります。" },
  { id: "ntt_math_0032", subject: "math", category: "小数", level: 1, type: "input", question: "1.5 × 7 を計算しなさい。", answer: "10.5", steps: ["1.5 × 7 = 10.5"], explanation: "小数×整数は、いったん小数点を無視して整数どうしのかけ算をしてから、あとで小数点の位置を戻すと計算しやすくなります。1.5×7=10.5になります。" },
  { id: "ntt_math_0033", subject: "math", category: "一次方程式", level: 2, type: "input", question: "2x + 8 = 6 を解きなさい。xの値を答えなさい。", answer: "-1", steps: ["2x = 6 - (8)", "2x = -2", "x = -2 ÷ 2 = -1"], explanation: "方程式を解くときは、xの項を左辺に、数だけの項を右辺に移項して整理します。「+8」を右辺に移項すると符号が反対の「-8」になります。最後に両辺をxの係数2で割ってxを求めます。" },
  { id: "ntt_math_0034", subject: "math", category: "割合", level: 1, type: "choice", question: "70人の10%は何人ですか?", choices: ["7人", "12人", "2人", "14人"], answer: "7人", steps: ["10% = 10/100", "70 × 10 ÷ 100 = 7"], explanation: "「○%」は「100人あたり○人の割合」という意味なので、割合を計算するときは百分率を100で割って小数(または分数)に直してからかけます。10%=10/100なので、70×10/100=7人になります。" },
  { id: "ntt_math_0035", subject: "math", category: "割合", level: 5, type: "input", question: "定価800円の商品を25%値上げした後、さらにそこから25%値引きした。最終的な価格はいくらですか?", answer: "750円", steps: ["値上げ後: 800 × (100+25) ÷ 100 = 1000", "値引き後: 1000 × (100-25) ÷ 100 = 750"], explanation: "割合の変化が2回続く問題では、1回ごとに順番に計算していきます。値上げ後の価格を先に求め、その新しい価格を基準にして値引きを計算する点に注意してください(最初の定価をもとに値引き額を計算するのではありません)。" },
  { id: "ntt_math_0036", subject: "math", category: "単位換算", level: 1, type: "input", question: "1.8mは何cmですか?", answer: "180cm", steps: ["1m = 100cm", "1.8 × 100 = 180", "よって 180cm"], explanation: "単位を換算するときは、まず1mが何cmにあたるかを確認します。1m=100cmなので、1.8mはその1.8倍で180cmになります。" },
  { id: "ntt_math_0037", subject: "math", category: "比例・反比例", level: 2, type: "input", question: "yはxに比例し、x=10のときy=40である。x=3のときのyの値を求めなさい。", answer: "12", steps: ["比例定数 k = 40 ÷ 10 = 4", "y = 4 × 3 = 12"], explanation: "yがxに比例するとき、y=k×xという式が成り立ち、kを比例定数といいます。まず与えられた条件からkを求め、そのkを使って求めたいyの値を計算します。" },
  { id: "ntt_math_0038", subject: "math", category: "二次関数", level: 4, type: "choice", question: "y = x² + 6x + 22 の頂点の座標を求めなさい。", choices: ["(-3, 13)", "(-2, 13)", "(-3, 14)", "(3, 13)"], answer: "(-3, 13)", steps: ["y = x² + 6x + 22 を平方完成する", "y = (x - (-3))² + 13", "頂点は (-3, 13)"], explanation: "二次関数の頂点を求めるには「平方完成」という変形を行い、y=(x-p)²+qの形にします。この形になれば、頂点の座標は(p, q)であるとすぐに分かります。" },
  { id: "ntt_math_0039", subject: "math", category: "速さ・時間・距離", level: 5, type: "input", question: "56km離れた地点からAさんとBさんが同時に向かい合って出発した。Aさんは時速4km、Bさんは時速4kmで進むとき、2人が出会うのは何時間後ですか?", answer: "7時間後", steps: ["2人の速さの和: 4 + 4 = 8km/時", "出会うまでの時間: 56 ÷ 8 = 7時間"], explanation: "2人が向かい合って進むとき、2人の間の距離は「2人の速さの和」の速さで縮まっていきます。したがって、2人の速さを足したものを「合わせた速さ」として、通常の距離÷速さの計算で出会うまでの時間が求められます。" },
  { id: "ntt_math_0040", subject: "math", category: "図形", level: 3, type: "input", question: "直角三角形の直角をはさむ2辺の長さが7cmと24cmのとき、斜辺の長さを求めなさい。", answer: "25cm", steps: ["7² + 24² = 49 + 576 = 625", "√625 = 25"], explanation: "直角三角形では「(斜辺)²=(辺1)²+(辺2)²」という三平方の定理(ピタゴラスの定理)が成り立ちます。2辺の2乗の和を求めてから平方根をとると斜辺の長さが分かります。" },
  { id: "ntt_math_0041", subject: "math", category: "小数", level: 1, type: "input", question: "13.67 - 1.91 を計算しなさい。", answer: "11.76", steps: ["小数点の位置をそろえる", "13.67 - 1.91 = 11.76"], explanation: "小数のひき算も、小数点の位置をそろえて筆算します。位をそろえて計算すると13.67-1.91=11.76になります。" },
  { id: "ntt_math_0042", subject: "math", category: "百分率", level: 2, type: "input", question: "定価7960円の品物を5%引きで買った。支払う金額はいくらですか?", answer: "7562円", steps: ["100 - 5 = 95(支払う割合は95%)", "7960 × 95 ÷ 100 = 7562"], explanation: "5%引きということは、定価の(100-5)%を支払うことになります。定価に(100-5)/100をかけると、実際に支払う金額が求められます。" },
  { id: "ntt_math_0043", subject: "math", category: "二次方程式", level: 3, type: "choice", question: "x² + 13x + 42 = 0 を解きなさい。", choices: ["x=-7, -6", "x=-6, -6", "x=-7, -5", "x=7, 6"], answer: "x=-7, -6", steps: ["かけて42、足して-13になる2数を探す → -7 と -6", "(x-(-7))(x-(-6)) = 0", "x = -7, -6"], explanation: "二次方程式は、左辺を(x-○)(x-△)の形に因数分解できれば、○と△が解になります。かけて42、足して-13になる2つの数を探すと-7と-6が見つかります。" },
  { id: "ntt_math_0044", subject: "math", category: "消費税", level: 2, type: "input", question: "税抜き7630円の商品に消費税10%がかかるとき、税込み価格はいくらですか?", answer: "8393円", steps: ["消費税額: 7630 × 10 ÷ 100 = 763", "税込み価格: 7630 + 763 = 8393"], explanation: "税込み価格は「税抜き価格+消費税額」で求めます。消費税額は税抜き価格に税率(%)をかけて100で割ることで計算できます。" },
  { id: "ntt_math_0045", subject: "math", category: "鶴亀算", level: 5, type: "input", question: "鶴と亀が合わせて35匹おり、足の合計本数は102本である。鶴は何匹いますか?", answer: "19匹", steps: ["全部鶴と仮定: 35 × 2 = 70本", "実際との差: 102 - 70 = 32本", "亀の数: 32 ÷ 2 = 16匹", "鶴の数: 35 - 16 = 19匹"], explanation: "鶴亀算の定番の解き方は「全部鶴だったと仮定する」ことです。全部鶴なら足の合計は35×2=70本になるはずですが、実際は102本なのでその差は亀が混じっている分です。亀1匹につき鶴より足が2本多いので、差を2で割ると亀の数が分かります。" },
  { id: "ntt_math_0046", subject: "math", category: "消費税", level: 2, type: "input", question: "税抜き9660円の商品に消費税10%がかかるとき、税込み価格はいくらですか?", answer: "10626円", steps: ["消費税額: 9660 × 10 ÷ 100 = 966", "税込み価格: 9660 + 966 = 10626"], explanation: "税込み価格は「税抜き価格+消費税額」で求めます。消費税額は税抜き価格に税率(%)をかけて100で割ることで計算できます。" },
  { id: "ntt_math_0047", subject: "math", category: "整数", level: 1, type: "input", question: "50と24の最大公約数を求めなさい。", answer: "2", steps: ["50を割り切れる数、24を割り切れる数をそれぞれ書き出す", "共通する約数のうち最大のものが2"], explanation: "最大公約数とは、2つの数を共に割り切ることができる整数のうち、最も大きいものです。50の約数と24の約数を比べると、共通する最大の約数は2です。" },
  { id: "ntt_math_0048", subject: "math", category: "正負の数", level: 1, type: "input", question: "(-9) × (-4) を計算しなさい。", answer: "36", steps: ["絶対値どうしをかける: 9 × 4 = 36", "符号を決める", "(-9) × (-4) = 36"], explanation: "正負の数のかけ算では、符号の異なる数どうしの積は負に、同じ符号どうしの積は正になります。絶対値どうしをかけた後に符号を決めると、(-9)×(-4)=36になります。" },
  { id: "ntt_math_0049", subject: "math", category: "鶴亀算", level: 5, type: "input", question: "鶴と亀が合わせて36匹おり、足の合計本数は110本である。鶴は何匹いますか?", answer: "17匹", steps: ["全部鶴と仮定: 36 × 2 = 72本", "実際との差: 110 - 72 = 38本", "亀の数: 38 ÷ 2 = 19匹", "鶴の数: 36 - 19 = 17匹"], explanation: "鶴亀算の定番の解き方は「全部鶴だったと仮定する」ことです。全部鶴なら足の合計は36×2=72本になるはずですが、実際は110本なのでその差は亀が混じっている分です。亀1匹につき鶴より足が2本多いので、差を2で割ると亀の数が分かります。" },
  { id: "ntt_math_0050", subject: "math", category: "四則演算", level: 1, type: "input", question: "9 + 9 × 13 を計算しなさい。", answer: "126", steps: ["9 × 13 = 117", "9 + 117 = 126"], explanation: "計算の順序のルールとして、かけ算・わり算はたし算・ひき算より先に計算します。まず9×13を計算してから9を足します。" },
  { id: "ntt_math_0051", subject: "math", category: "単位換算", level: 1, type: "input", question: "9.4Lは何mLですか?", answer: "9400mL", steps: ["1L = 1000mL", "9.4 × 1000 = 9400", "よって 9400mL"], explanation: "単位を換算するときは、まず1Lが何mLにあたるかを確認します。1L=1000mLなので、9.4Lはその9.4倍で9400mLになります。" },
  { id: "ntt_math_0052", subject: "math", category: "小数", level: 1, type: "input", question: "6.4 × 4 を計算しなさい。", answer: "25.6", steps: ["6.4 × 4 = 25.6"], explanation: "小数×整数は、いったん小数点を無視して整数どうしのかけ算をしてから、あとで小数点の位置を戻すと計算しやすくなります。6.4×4=25.6になります。" },
  { id: "ntt_math_0053", subject: "math", category: "速さ・時間・距離", level: 5, type: "input", question: "40km離れた地点からAさんとBさんが同時に向かい合って出発した。Aさんは時速2km、Bさんは時速3kmで進むとき、2人が出会うのは何時間後ですか?", answer: "8時間後", steps: ["2人の速さの和: 2 + 3 = 5km/時", "出会うまでの時間: 40 ÷ 5 = 8時間"], explanation: "2人が向かい合って進むとき、2人の間の距離は「2人の速さの和」の速さで縮まっていきます。したがって、2人の速さを足したものを「合わせた速さ」として、通常の距離÷速さの計算で出会うまでの時間が求められます。" },
  { id: "ntt_math_0054", subject: "math", category: "連立方程式", level: 2, type: "input", question: "連立方程式 3x + 4y = 60, 1x + 5y = 53 を解いたとき、xの値を求めなさい。", answer: "8", steps: ["1つ目の式×5: 15x + 20y = 300", "2つ目の式×4: 4x + 20y = 212", "辺々を引くとyが消える: 11x = 88", "x = 88 ÷ 11 = 8"], explanation: "連立方程式は「加減法」で解くことができます。yの係数をそろえてから2つの式を引き算すると、yが消えてxだけの式になります。1つ目の式を5倍、2つ目の式を4倍すると、どちらもyの係数が20になるので、引き算でyを消去できます。" },
  { id: "ntt_math_0055", subject: "math", category: "場合の数", level: 4, type: "input", question: "異なる6個から1個を選んで並べる方法(順列)は何通りありますか?", answer: "6通り", steps: ["6 = 6"], explanation: "順序を区別して並べる「順列」は、1番目に選べるものが6通り、2番目は残りの5通り、というように1つずつ減らしながらかけ合わせます。" },
  { id: "ntt_math_0056", subject: "math", category: "一次方程式", level: 2, type: "input", question: "6x + 22 = 106 を解きなさい。xの値を答えなさい。", answer: "14", steps: ["6x = 106 - (22)", "6x = 84", "x = 84 ÷ 6 = 14"], explanation: "方程式を解くときは、xの項を左辺に、数だけの項を右辺に移項して整理します。「+22」を右辺に移項すると符号が反対の「-22」になります。最後に両辺をxの係数6で割ってxを求めます。" },
  { id: "ntt_math_0057", subject: "math", category: "確率", level: 4, type: "input", question: "大小2つのサイコロを同時に振るとき、目の和が4になる確率を求めなさい。", answer: "1/12", steps: ["目の和が4になる組: (1,3)、(2,2)、(3,1)", "全体は6×6=36通り", "確率 = 3/36 = 1/12"], explanation: "大小2つのサイコロの目の出方は全部で6×6=36通りあります。そのうち目の和が4になる組み合わせを数え上げると3通りあります。" },
  { id: "ntt_math_0058", subject: "math", category: "割合", level: 5, type: "input", question: "定価9400円の商品を10%値上げした後、さらにそこから10%値引きした。最終的な価格はいくらですか?", answer: "9306円", steps: ["値上げ後: 9400 × (100+10) ÷ 100 = 10340", "値引き後: 10340 × (100-10) ÷ 100 = 9306"], explanation: "割合の変化が2回続く問題では、1回ごとに順番に計算していきます。値上げ後の価格を先に求め、その新しい価格を基準にして値引きを計算する点に注意してください(最初の定価をもとに値引き額を計算するのではありません)。" },
  { id: "ntt_math_0059", subject: "math", category: "二次関数", level: 4, type: "choice", question: "y = x² - 8x + 6 の頂点の座標を求めなさい。", choices: ["(4, -10)", "(5, -10)", "(4, -9)", "(-4, -10)"], answer: "(4, -10)", steps: ["y = x² - 8x + 6 を平方完成する", "y = (x - (4))² + -10", "頂点は (4, -10)"], explanation: "二次関数の頂点を求めるには「平方完成」という変形を行い、y=(x-p)²+qの形にします。この形になれば、頂点の座標は(p, q)であるとすぐに分かります。" },
  { id: "ntt_math_0060", subject: "math", category: "分数", level: 1, type: "input", question: "5/9 + 5/3 を計算しなさい(答えは既約分数で)。", answer: "20/9", steps: ["分母を9にそろえる(通分)", "分子どうしを足す", "約分すると 20/9"], explanation: "分母の違う分数をたすときは、まず通分して分母をそろえる必要があります。9と3の最小公倍数9に通分してから分子どうしを足し、最後に約分すると20/9になります。" },
  { id: "ntt_math_0061", subject: "math", category: "平均", level: 1, type: "input", question: "4個の数 24、40、10、46 の平均を求めなさい。", answer: "30", steps: ["24+40+10+46 = 120", "120 ÷ 4 = 30"], explanation: "平均とは、いくつかの数を均等にならしたときの値のことで、「合計÷個数」で求めます。まずすべての数を足し合わせ、その合計を個数で割ります。" },
  { id: "ntt_math_0062", subject: "math", category: "金額計算", level: 1, type: "input", question: "530円の品物を買うのに5000円出しました。おつりはいくらですか?", answer: "4470円", steps: ["5000 - 530 = 4470"], explanation: "おつりは「支払った金額-品物の値段」で求めます。5000円出して530円の品物を買ったので、5000-530=4470円がおつりになります。" },
  { id: "ntt_math_0063", subject: "math", category: "二次方程式", level: 3, type: "choice", question: "x² + 9x + 8 = 0 を解きなさい。", choices: ["x=-8, -1", "x=-7, -1", "x=-8, 0", "x=8, 1"], answer: "x=-8, -1", steps: ["かけて8、足して-9になる2数を探す → -8 と -1", "(x-(-8))(x-(-1)) = 0", "x = -8, -1"], explanation: "二次方程式は、左辺を(x-○)(x-△)の形に因数分解できれば、○と△が解になります。かけて8、足して-9になる2つの数を探すと-8と-1が見つかります。" },
  { id: "ntt_math_0064", subject: "math", category: "小数", level: 1, type: "input", question: "20.52 + 12.8 を計算しなさい。", answer: "33.32", steps: ["小数点の位置をそろえる", "20.52 + 12.8 = 33.32"], explanation: "小数のたし算は、小数点の位置をそろえて筆算するのが基本です。位をそろえて計算すると20.52+12.8=33.32になります。" },
  { id: "ntt_math_0065", subject: "math", category: "百分率", level: 2, type: "input", question: "定価4380円の品物を15%引きで買った。支払う金額はいくらですか?", answer: "3723円", steps: ["100 - 15 = 85(支払う割合は85%)", "4380 × 85 ÷ 100 = 3723"], explanation: "15%引きということは、定価の(100-15)%を支払うことになります。定価に(100-15)/100をかけると、実際に支払う金額が求められます。" },
  { id: "ntt_math_0066", subject: "math", category: "連立方程式", level: 2, type: "input", question: "連立方程式 3x + 5y = 58, 1x + 3y = 26 を解いたとき、xの値を求めなさい。", answer: "11", steps: ["1つ目の式×3: 9x + 15y = 174", "2つ目の式×5: 5x + 15y = 130", "辺々を引くとyが消える: 4x = 44", "x = 44 ÷ 4 = 11"], explanation: "連立方程式は「加減法」で解くことができます。yの係数をそろえてから2つの式を引き算すると、yが消えてxだけの式になります。1つ目の式を3倍、2つ目の式を5倍すると、どちらもyの係数が15になるので、引き算でyを消去できます。" },
  { id: "ntt_math_0067", subject: "math", category: "場合の数", level: 4, type: "input", question: "異なる3個から3個を選んで並べる方法(順列)は何通りありますか?", answer: "6通り", steps: ["3 × 2 × 1 = 6"], explanation: "順序を区別して並べる「順列」は、1番目に選べるものが3通り、2番目は残りの2通り、というように1つずつ減らしながらかけ合わせます。" },
  { id: "ntt_math_0068", subject: "math", category: "図形", level: 3, type: "input", question: "縦16cm、横20cmの長方形の周りの長さを求めなさい。", answer: "72cm", steps: ["周りの長さ = (縦 + 横) × 2", "(16 + 20) × 2 = 72"], explanation: "長方形の周りの長さは、縦と横をそれぞれ2辺ずつ持つので「(縦+横)×2」で求めます。" },
  { id: "ntt_math_0069", subject: "math", category: "小数", level: 1, type: "input", question: "8.9 × 6 を計算しなさい。", answer: "53.4", steps: ["8.9 × 6 = 53.4"], explanation: "小数×整数は、いったん小数点を無視して整数どうしのかけ算をしてから、あとで小数点の位置を戻すと計算しやすくなります。8.9×6=53.4になります。" },
  { id: "ntt_math_0070", subject: "math", category: "一次方程式", level: 2, type: "input", question: "8x - 10 = -2 を解きなさい。xの値を答えなさい。", answer: "1", steps: ["8x = -2 - (-10)", "8x = 8", "x = 8 ÷ 8 = 1"], explanation: "方程式を解くときは、xの項を左辺に、数だけの項を右辺に移項して整理します。「+10」を右辺に移項すると符号が反対の「-10」になります。最後に両辺をxの係数8で割ってxを求めます。" },
  { id: "ntt_math_0071", subject: "math", category: "損益算", level: 5, type: "input", question: "原価8200円の商品に30%の利益を見込んで定価をつけた。定価はいくらですか?", answer: "10660円", steps: ["利益額: 8200 × 30 ÷ 100 = 2460", "定価: 8200 + 2460 = 10660"], explanation: "「○%の利益を見込む」ということは、原価に原価の○%を上乗せするということです。定価は「原価×(100+○)/100」で求められます。" },
  { id: "ntt_math_0072", subject: "math", category: "速さ・時間・距離", level: 2, type: "input", question: "時速54kmで2時間進むと、何km進みますか?", answer: "108km", steps: ["距離 = 速さ × 時間", "54 × 2 = 108"], explanation: "「距離=速さ×時間」という公式に、速さと時間の値をそのまま当てはめて計算します。" },
  { id: "ntt_math_0073", subject: "math", category: "割合", level: 1, type: "choice", question: "20人の50%は何人ですか?", choices: ["10人", "15人", "5人", "20人"], answer: "10人", steps: ["50% = 50/100", "20 × 50 ÷ 100 = 10"], explanation: "「○%」は「100人あたり○人の割合」という意味なので、割合を計算するときは百分率を100で割って小数(または分数)に直してからかけます。50%=50/100なので、20×50/100=10人になります。" },
  { id: "ntt_math_0074", subject: "math", category: "二次関数", level: 4, type: "choice", question: "y = x² + 2x - 8 の頂点の座標を求めなさい。", choices: ["(-1, -9)", "(0, -9)", "(-1, -8)", "(1, -9)"], answer: "(-1, -9)", steps: ["y = x² + 2x - 8 を平方完成する", "y = (x - (-1))² + -9", "頂点は (-1, -9)"], explanation: "二次関数の頂点を求めるには「平方完成」という変形を行い、y=(x-p)²+qの形にします。この形になれば、頂点の座標は(p, q)であるとすぐに分かります。" },
  { id: "ntt_math_0075", subject: "math", category: "確率", level: 3, type: "input", question: "サイコロを1回振って、5以下の目が出る確率を求めなさい。", answer: "5/6", steps: ["5以下の目: 1, 2, 3, 4, 5(5通り)", "全体は6通り", "確率 = 5/6 = 5/6"], explanation: "確率は「求める場合の数÷すべての場合の数」で計算します。サイコロの目の出方は全部で6通りあり、そのうち5以下の目は5通りあります。" },
  { id: "ntt_math_0076", subject: "math", category: "確率", level: 3, type: "input", question: "赤玉1個、白玉6個が入った袋から1個取り出すとき、赤玉が出る確率を求めなさい。", answer: "1/7", steps: ["全体の玉の数: 1 + 6 = 7個", "確率 = 1/7 = 1/7"], explanation: "確率は「求める場合の数÷すべての場合の数」で計算します。袋の中の玉は全部で7個あり、そのうち赤玉は1個です。" },
  { id: "ntt_math_0077", subject: "math", category: "図形と計量", level: 4, type: "choice", question: "tan45° の値を求めなさい。", choices: ["1", "0", "1/2", "√2/2"], answer: "1", explanation: "tan45°=1という三角比の基本値です。45°の直角二等辺三角形では、対辺と隣辺の長さが等しいのでtan45°=1になります。" },
  { id: "ntt_math_0078", subject: "math", category: "二次方程式", level: 3, type: "choice", question: "x² - 14x + 48 = 0 を解きなさい。", choices: ["x=6, 8", "x=7, 8", "x=6, 9", "x=-6, -8"], answer: "x=6, 8", steps: ["かけて48、足して14になる2数を探す → 6 と 8", "(x-(6))(x-(8)) = 0", "x = 6, 8"], explanation: "二次方程式は、左辺を(x-○)(x-△)の形に因数分解できれば、○と△が解になります。かけて48、足して14になる2つの数を探すと6と8が見つかります。" },
  { id: "ntt_math_0079", subject: "math", category: "仕事算", level: 5, type: "input", question: "ある作業をAさん1人で行うと9日、Bさん1人で行うと18日かかる。2人で一緒に行うと何日で終わりますか?", answer: "6日", steps: ["Aさんの1日の仕事量: 1/9、Bさんの1日の仕事量: 1/18", "2人合わせた1日の仕事量: 1/9 + 1/18 = 27/162", "かかる日数 = 1 ÷ (27/162) = 162/27 = 6日"], explanation: "仕事全体の量を1とすると、Aさんは1日に1/9、Bさんは1日に1/18の仕事をこなします。2人が一緒に働くと1日あたりの仕事量はその合計になるので、全体の1をその合計で割ると完成にかかる日数が求められます。" },
  { id: "ntt_math_0080", subject: "math", category: "金額計算", level: 1, type: "input", question: "550円の品物を買うのに2000円出しました。おつりはいくらですか?", answer: "1450円", steps: ["2000 - 550 = 1450"], explanation: "おつりは「支払った金額-品物の値段」で求めます。2000円出して550円の品物を買ったので、2000-550=1450円がおつりになります。" },
  { id: "ntt_math_0081", subject: "math", category: "二次方程式", level: 3, type: "choice", question: "x² - 4x - 32 = 0 を解きなさい。", choices: ["x=-4, 8", "x=-3, 8", "x=-4, 9", "x=4, -8"], answer: "x=-4, 8", steps: ["かけて-32、足して4になる2数を探す → -4 と 8", "(x-(-4))(x-(8)) = 0", "x = -4, 8"], explanation: "二次方程式は、左辺を(x-○)(x-△)の形に因数分解できれば、○と△が解になります。かけて-32、足して4になる2つの数を探すと-4と8が見つかります。" },
  { id: "ntt_math_0082", subject: "math", category: "正負の数", level: 1, type: "input", question: "(19) - (12) を計算しなさい。", answer: "7", steps: ["(19) - (12) = (19) + (-12)", "= 7"], explanation: "正負の数のひき算は、引く数の符号を反対にしてたし算に直すと考えやすくなります。(19)-(12)=(19)+(-12)=7になります。" },
  { id: "ntt_math_0083", subject: "math", category: "四則演算", level: 1, type: "input", question: "9 + 10 × 17 を計算しなさい。", answer: "179", steps: ["10 × 17 = 170", "9 + 170 = 179"], explanation: "計算の順序のルールとして、かけ算・わり算はたし算・ひき算より先に計算します。まず10×17を計算してから9を足します。" },
  { id: "ntt_math_0084", subject: "math", category: "仕事算", level: 5, type: "input", question: "ある作業をAさん1人で行うと21日、Bさん1人で行うと28日かかる。2人で一緒に行うと何日で終わりますか?", answer: "12日", steps: ["Aさんの1日の仕事量: 1/21、Bさんの1日の仕事量: 1/28", "2人合わせた1日の仕事量: 1/21 + 1/28 = 49/588", "かかる日数 = 1 ÷ (49/588) = 588/49 = 12日"], explanation: "仕事全体の量を1とすると、Aさんは1日に1/21、Bさんは1日に1/28の仕事をこなします。2人が一緒に働くと1日あたりの仕事量はその合計になるので、全体の1をその合計で割ると完成にかかる日数が求められます。" },
  { id: "ntt_math_0085", subject: "math", category: "百分率", level: 2, type: "input", question: "定価6480円の品物を20%引きで買った。支払う金額はいくらですか?", answer: "5184円", steps: ["100 - 20 = 80(支払う割合は80%)", "6480 × 80 ÷ 100 = 5184"], explanation: "20%引きということは、定価の(100-20)%を支払うことになります。定価に(100-20)/100をかけると、実際に支払う金額が求められます。" },
  { id: "ntt_math_0086", subject: "math", category: "平方根", level: 3, type: "input", question: "√20 を最も簡単な形(a√b)に変形したとき、根号の外に出る数(a)を求めなさい。", answer: "2", steps: ["20 を素因数分解して 2² × 5 の形にする", "√(2² × 5) = 2√5"], explanation: "根号の中に同じ数の2乗の形(平方数)が含まれているとき、その数は根号の外に出すことができます。20=2²×5と分解できるので、2²の部分が根号の外に出て2√5になります。" },
  { id: "ntt_math_0087", subject: "math", category: "確率", level: 4, type: "input", question: "大小2つのサイコロを同時に振るとき、目の和が10になる確率を求めなさい。", answer: "1/12", steps: ["目の和が10になる組: (4,6)、(5,5)、(6,4)", "全体は6×6=36通り", "確率 = 3/36 = 1/12"], explanation: "大小2つのサイコロの目の出方は全部で6×6=36通りあります。そのうち目の和が10になる組み合わせを数え上げると3通りあります。" },
  { id: "ntt_math_0088", subject: "math", category: "金額計算", level: 1, type: "input", question: "80円の品物を買うのに1000円出しました。おつりはいくらですか?", answer: "920円", steps: ["1000 - 80 = 920"], explanation: "おつりは「支払った金額-品物の値段」で求めます。1000円出して80円の品物を買ったので、1000-80=920円がおつりになります。" },
  { id: "ntt_math_0089", subject: "math", category: "一次方程式", level: 2, type: "input", question: "8x + 12 = -52 を解きなさい。xの値を答えなさい。", answer: "-8", steps: ["8x = -52 - (12)", "8x = -64", "x = -64 ÷ 8 = -8"], explanation: "方程式を解くときは、xの項を左辺に、数だけの項を右辺に移項して整理します。「+12」を右辺に移項すると符号が反対の「-12」になります。最後に両辺をxの係数8で割ってxを求めます。" },
  { id: "ntt_math_0090", subject: "math", category: "二次方程式", level: 3, type: "choice", question: "x² - 13x + 40 = 0 を解きなさい。", choices: ["x=5, 8", "x=6, 8", "x=5, 9", "x=-5, -8"], answer: "x=5, 8", steps: ["かけて40、足して13になる2数を探す → 5 と 8", "(x-(5))(x-(8)) = 0", "x = 5, 8"], explanation: "二次方程式は、左辺を(x-○)(x-△)の形に因数分解できれば、○と△が解になります。かけて40、足して13になる2つの数を探すと5と8が見つかります。" },
  { id: "ntt_math_0091", subject: "math", category: "平方根", level: 3, type: "input", question: "√144 の値を求めなさい。", answer: "12", steps: ["12 × 12 = 144", "よって √144 = 12"], explanation: "√144(ルート144)とは、2乗すると144になる正の数のことです。12を2乗すると12×12=144になるので、√144=12です。" },
  { id: "ntt_math_0092", subject: "math", category: "平方根", level: 3, type: "input", question: "√36 の値を求めなさい。", answer: "6", steps: ["6 × 6 = 36", "よって √36 = 6"], explanation: "√36(ルート36)とは、2乗すると36になる正の数のことです。6を2乗すると6×6=36になるので、√36=6です。" },
  { id: "ntt_math_0093", subject: "math", category: "速さ・時間・距離", level: 2, type: "input", question: "93kmの道のりを1時間で進むと、時速は何kmですか?", answer: "時速93km", steps: ["速さ = 距離 ÷ 時間", "93 ÷ 1 = 93"], explanation: "「速さ=距離÷時間」という公式を使います。1時間あたりに進む距離を求めることになります。" },
  { id: "ntt_math_0094", subject: "math", category: "比", level: 2, type: "input", question: "A:B = 9:2 で A=18 のとき、Bの値を求めなさい。", answer: "4", steps: ["18 ÷ 9 = 2倍", "2 × 2 = 4"], explanation: "比が等しいとき、A:B=9:2という関係はどれだけ数が大きくなっても保たれます。AがA=18になったのは、もとの比の9を何倍したかを考えると、B=2にも同じ倍率をかければ求められます。" },
  { id: "ntt_math_0095", subject: "math", category: "正負の数", level: 1, type: "input", question: "(14) - (-1) を計算しなさい。", answer: "15", steps: ["(14) - (-1) = (14) + (1)", "= 15"], explanation: "正負の数のひき算は、引く数の符号を反対にしてたし算に直すと考えやすくなります。(14)-(-1)=(14)+(1)=15になります。" },
  { id: "ntt_math_0096", subject: "math", category: "分数", level: 1, type: "input", question: "5/7 - 4/9 を計算しなさい(答えは既約分数で)。", answer: "17/63", steps: ["分母を63にそろえる(通分)", "分子どうしを引く", "約分すると 17/63"], explanation: "分母の違う分数をひくときも、まず通分して分母をそろえます。7と9の最小公倍数63に通分してから分子どうしを引き、最後に約分すると17/63になります。" },
  { id: "ntt_math_0097", subject: "math", category: "整数", level: 1, type: "input", question: "12と58の最小公倍数を求めなさい。", answer: "348", steps: ["12と58の最大公約数は2", "12 × 58 ÷ 2 = 348"], explanation: "最小公倍数とは、2つの数のどちらの倍数にもなっている整数のうち、最も小さいものです。最大公約数を使うと (最小公倍数)=(12×58)÷(最大公約数) で求められます。" },
  { id: "ntt_math_0098", subject: "math", category: "速さ・時間・距離", level: 2, type: "input", question: "144kmの道のりを4時間で進むと、時速は何kmですか?", answer: "時速36km", steps: ["速さ = 距離 ÷ 時間", "144 ÷ 4 = 36"], explanation: "「速さ=距離÷時間」という公式を使います。1時間あたりに進む距離を求めることになります。" },
  { id: "ntt_math_0099", subject: "math", category: "消費税", level: 2, type: "input", question: "税抜き1530円の商品に消費税10%がかかるとき、税込み価格はいくらですか?", answer: "1683円", steps: ["消費税額: 1530 × 10 ÷ 100 = 153", "税込み価格: 1530 + 153 = 1683"], explanation: "税込み価格は「税抜き価格+消費税額」で求めます。消費税額は税抜き価格に税率(%)をかけて100で割ることで計算できます。" },
  { id: "ntt_math_0100", subject: "math", category: "比", level: 2, type: "input", question: "A:B = 3:5 で A=9 のとき、Bの値を求めなさい。", answer: "15", steps: ["9 ÷ 3 = 3倍", "5 × 3 = 15"], explanation: "比が等しいとき、A:B=3:5という関係はどれだけ数が大きくなっても保たれます。AがA=9になったのは、もとの比の3を何倍したかを考えると、B=5にも同じ倍率をかければ求められます。" },
  { id: "ntt_math_0101", subject: "math", category: "正負の数", level: 1, type: "input", question: "(-14) - (7) を計算しなさい。", answer: "-21", steps: ["(-14) - (7) = (-14) + (-7)", "= -21"], explanation: "正負の数のひき算は、引く数の符号を反対にしてたし算に直すと考えやすくなります。(-14)-(7)=(-14)+(-7)=-21になります。" },
  { id: "ntt_math_0102", subject: "math", category: "四則演算", level: 1, type: "input", question: "18 + 30 ÷ 5 を計算しなさい。", answer: "24", steps: ["30 ÷ 5 = 6", "18 + 6 = 24"], explanation: "わり算はたし算より先に計算するというルールに従い、まず30÷5を計算してから18を足します。" },
  { id: "ntt_math_0103", subject: "math", category: "正負の数", level: 1, type: "input", question: "(-5) - (12) を計算しなさい。", answer: "-17", steps: ["(-5) - (12) = (-5) + (-12)", "= -17"], explanation: "正負の数のひき算は、引く数の符号を反対にしてたし算に直すと考えやすくなります。(-5)-(12)=(-5)+(-12)=-17になります。" },
  { id: "ntt_math_0104", subject: "math", category: "場合の数", level: 4, type: "input", question: "異なる3個から2個を選んで並べる方法(順列)は何通りありますか?", answer: "6通り", steps: ["3 × 2 = 6"], explanation: "順序を区別して並べる「順列」は、1番目に選べるものが3通り、2番目は残りの2通り、というように1つずつ減らしながらかけ合わせます。" },
  { id: "ntt_math_0105", subject: "math", category: "分数", level: 1, type: "input", question: "4/5 + 5/6 を計算しなさい(答えは既約分数で)。", answer: "49/30", steps: ["分母を30にそろえる(通分)", "分子どうしを足す", "約分すると 49/30"], explanation: "分母の違う分数をたすときは、まず通分して分母をそろえる必要があります。5と6の最小公倍数30に通分してから分子どうしを足し、最後に約分すると49/30になります。" },
  { id: "ntt_math_0106", subject: "math", category: "百分率", level: 2, type: "input", question: "定価8160円の品物を10%引きで買った。支払う金額はいくらですか?", answer: "7344円", steps: ["100 - 10 = 90(支払う割合は90%)", "8160 × 90 ÷ 100 = 7344"], explanation: "10%引きということは、定価の(100-10)%を支払うことになります。定価に(100-10)/100をかけると、実際に支払う金額が求められます。" },
  { id: "ntt_math_0107", subject: "math", category: "確率", level: 3, type: "input", question: "赤玉8個、白玉6個が入った袋から1個取り出すとき、赤玉が出る確率を求めなさい。", answer: "4/7", steps: ["全体の玉の数: 8 + 6 = 14個", "確率 = 8/14 = 4/7"], explanation: "確率は「求める場合の数÷すべての場合の数」で計算します。袋の中の玉は全部で14個あり、そのうち赤玉は8個です。" },
  { id: "ntt_math_0108", subject: "math", category: "連立方程式", level: 2, type: "input", question: "連立方程式 5x + 1y = 70, 3x + 3y = 66 を解いたとき、xの値を求めなさい。", answer: "12", steps: ["1つ目の式×3: 15x + 3y = 210", "2つ目の式×1: 3x + 3y = 66", "辺々を引くとyが消える: 12x = 144", "x = 144 ÷ 12 = 12"], explanation: "連立方程式は「加減法」で解くことができます。yの係数をそろえてから2つの式を引き算すると、yが消えてxだけの式になります。1つ目の式を3倍、2つ目の式を1倍すると、どちらもyの係数が3になるので、引き算でyを消去できます。" },
  { id: "ntt_math_0109", subject: "math", category: "分数", level: 1, type: "input", question: "1 - 1/3 を計算しなさい(答えは既約分数で)。", answer: "2/3", steps: ["分母を3にそろえる(通分)", "分子どうしを引く", "約分すると 2/3"], explanation: "分母の違う分数をひくときも、まず通分して分母をそろえます。1と3の最小公倍数3に通分してから分子どうしを引き、最後に約分すると2/3になります。" },
  { id: "ntt_math_0110", subject: "math", category: "一次方程式", level: 2, type: "input", question: "7x - 30 = -128 を解きなさい。xの値を答えなさい。", answer: "-14", steps: ["7x = -128 - (-30)", "7x = -98", "x = -98 ÷ 7 = -14"], explanation: "方程式を解くときは、xの項を左辺に、数だけの項を右辺に移項して整理します。「+30」を右辺に移項すると符号が反対の「-30」になります。最後に両辺をxの係数7で割ってxを求めます。" },
  { id: "ntt_math_0111", subject: "math", category: "図形", level: 3, type: "input", question: "底辺5cm、高さ2cmの三角形の面積を求めなさい。", answer: "5cm²", steps: ["面積 = 底辺 × 高さ ÷ 2", "5 × 2 ÷ 2 = 5"], explanation: "三角形の面積は「底辺×高さ÷2」で求めます。長方形の面積(底辺×高さ)のちょうど半分になることをイメージすると覚えやすいです。" },
  { id: "ntt_math_0112", subject: "math", category: "四則演算", level: 1, type: "input", question: "3 + 7 × 18 を計算しなさい。", answer: "129", steps: ["7 × 18 = 126", "3 + 126 = 129"], explanation: "計算の順序のルールとして、かけ算・わり算はたし算・ひき算より先に計算します。まず7×18を計算してから3を足します。" },
  { id: "ntt_math_0113", subject: "math", category: "整数", level: 1, type: "input", question: "28と16の最小公倍数を求めなさい。", answer: "112", steps: ["28と16の最大公約数は4", "28 × 16 ÷ 4 = 112"], explanation: "最小公倍数とは、2つの数のどちらの倍数にもなっている整数のうち、最も小さいものです。最大公約数を使うと (最小公倍数)=(28×16)÷(最大公約数) で求められます。" },
  { id: "ntt_math_0114", subject: "math", category: "比例・反比例", level: 2, type: "input", question: "yはxに比例し、x=9のときy=18である。x=5のときのyの値を求めなさい。", answer: "10", steps: ["比例定数 k = 18 ÷ 9 = 2", "y = 2 × 5 = 10"], explanation: "yがxに比例するとき、y=k×xという式が成り立ち、kを比例定数といいます。まず与えられた条件からkを求め、そのkを使って求めたいyの値を計算します。" },
  { id: "ntt_math_0115", subject: "math", category: "単位換算", level: 1, type: "input", question: "10.5kgは何gですか?", answer: "10500g", steps: ["1kg = 1000g", "10.5 × 1000 = 10500", "よって 10500g"], explanation: "単位を換算するときは、まず1kgが何gにあたるかを確認します。1kg=1000gなので、10.5kgはその10.5倍で10500gになります。" },
  { id: "ntt_math_0116", subject: "math", category: "単位換算", level: 1, type: "input", question: "5.2mは何cmですか?", answer: "520cm", steps: ["1m = 100cm", "5.2 × 100 = 520", "よって 520cm"], explanation: "単位を換算するときは、まず1mが何cmにあたるかを確認します。1m=100cmなので、5.2mはその5.2倍で520cmになります。" },
  { id: "ntt_math_0117", subject: "math", category: "図形と計量", level: 4, type: "choice", question: "sin60° の値を求めなさい。", choices: ["√3/2", "0", "1", "1/2"], answer: "√3/2", explanation: "sin60°=√3/2という三角比の基本値です。30°-60°-90°の直角三角形の辺の比(1:2:√3)から求められます。" },
  { id: "ntt_math_0118", subject: "math", category: "正負の数", level: 1, type: "input", question: "(-14) + (8) を計算しなさい。", answer: "-6", steps: ["(-14) + (8) = -6"], explanation: "正負の数のたし算では、符号が同じ数どうしは絶対値を足して同じ符号をつけ、符号が異なる数どうしは絶対値の差をとって絶対値の大きい方の符号をつけます。(-14)+(8)=-6になります。" },
  { id: "ntt_math_0119", subject: "math", category: "百分率", level: 2, type: "input", question: "定価1320円の品物を10%引きで買った。支払う金額はいくらですか?", answer: "1188円", steps: ["100 - 10 = 90(支払う割合は90%)", "1320 × 90 ÷ 100 = 1188"], explanation: "10%引きということは、定価の(100-10)%を支払うことになります。定価に(100-10)/100をかけると、実際に支払う金額が求められます。" },
  { id: "ntt_math_0120", subject: "math", category: "確率", level: 4, type: "input", question: "大小2つのサイコロを同時に振るとき、目の和が2になる確率を求めなさい。", answer: "1/36", steps: ["目の和が2になる組: (1,1)", "全体は6×6=36通り", "確率 = 1/36 = 1/36"], explanation: "大小2つのサイコロの目の出方は全部で6×6=36通りあります。そのうち目の和が2になる組み合わせを数え上げると1通りあります。" },
  { id: "ntt_math_0121", subject: "math", category: "二次方程式", level: 3, type: "choice", question: "x² + 6x - 16 = 0 を解きなさい。", choices: ["x=-8, 2", "x=-7, 2", "x=-8, 3", "x=8, -2"], answer: "x=-8, 2", steps: ["かけて-16、足して-6になる2数を探す → -8 と 2", "(x-(-8))(x-(2)) = 0", "x = -8, 2"], explanation: "二次方程式は、左辺を(x-○)(x-△)の形に因数分解できれば、○と△が解になります。かけて-16、足して-6になる2つの数を探すと-8と2が見つかります。" },
  { id: "ntt_math_0122", subject: "math", category: "速さ・時間・距離", level: 5, type: "input", question: "28km離れた地点からAさんとBさんが同時に向かい合って出発した。Aさんは時速6km、Bさんは時速8kmで進むとき、2人が出会うのは何時間後ですか?", answer: "2時間後", steps: ["2人の速さの和: 6 + 8 = 14km/時", "出会うまでの時間: 28 ÷ 14 = 2時間"], explanation: "2人が向かい合って進むとき、2人の間の距離は「2人の速さの和」の速さで縮まっていきます。したがって、2人の速さを足したものを「合わせた速さ」として、通常の距離÷速さの計算で出会うまでの時間が求められます。" },
  { id: "ntt_math_0123", subject: "math", category: "図形と計量", level: 4, type: "choice", question: "cos0° の値を求めなさい。", choices: ["1", "0", "1/2", "√2/2"], answer: "1", explanation: "cos0°=1という三角比の基本値です。0°では単位円上の点のx座標が最大の1になります。" },
  { id: "ntt_math_0124", subject: "math", category: "二次方程式", level: 3, type: "choice", question: "x² + 1x - 72 = 0 を解きなさい。", choices: ["x=-9, 8", "x=-8, 8", "x=-9, 9", "x=9, -8"], answer: "x=-9, 8", steps: ["かけて-72、足して-1になる2数を探す → -9 と 8", "(x-(-9))(x-(8)) = 0", "x = -9, 8"], explanation: "二次方程式は、左辺を(x-○)(x-△)の形に因数分解できれば、○と△が解になります。かけて-72、足して-1になる2つの数を探すと-9と8が見つかります。" },
  { id: "ntt_math_0125", subject: "math", category: "一次方程式", level: 2, type: "input", question: "3x - 24 = -21 を解きなさい。xの値を答えなさい。", answer: "1", steps: ["3x = -21 - (-24)", "3x = 3", "x = 3 ÷ 3 = 1"], explanation: "方程式を解くときは、xの項を左辺に、数だけの項を右辺に移項して整理します。「+24」を右辺に移項すると符号が反対の「-24」になります。最後に両辺をxの係数3で割ってxを求めます。" },
  { id: "ntt_math_0126", subject: "math", category: "整数", level: 1, type: "input", question: "6と20の最大公約数を求めなさい。", answer: "2", steps: ["6を割り切れる数、20を割り切れる数をそれぞれ書き出す", "共通する約数のうち最大のものが2"], explanation: "最大公約数とは、2つの数を共に割り切ることができる整数のうち、最も大きいものです。6の約数と20の約数を比べると、共通する最大の約数は2です。" },
  { id: "ntt_math_0127", subject: "math", category: "消費税", level: 2, type: "input", question: "税抜き7340円の商品に消費税10%がかかるとき、税込み価格はいくらですか?", answer: "8074円", steps: ["消費税額: 7340 × 10 ÷ 100 = 734", "税込み価格: 7340 + 734 = 8074"], explanation: "税込み価格は「税抜き価格+消費税額」で求めます。消費税額は税抜き価格に税率(%)をかけて100で割ることで計算できます。" },
  { id: "ntt_math_0128", subject: "math", category: "一次方程式", level: 2, type: "input", question: "9x + 4 = 112 を解きなさい。xの値を答えなさい。", answer: "12", steps: ["9x = 112 - (4)", "9x = 108", "x = 108 ÷ 9 = 12"], explanation: "方程式を解くときは、xの項を左辺に、数だけの項を右辺に移項して整理します。「+4」を右辺に移項すると符号が反対の「-4」になります。最後に両辺をxの係数9で割ってxを求めます。" },
  { id: "ntt_math_0129", subject: "math", category: "鶴亀算", level: 5, type: "input", question: "鶴と亀が合わせて18匹おり、足の合計本数は42本である。鶴は何匹いますか?", answer: "15匹", steps: ["全部鶴と仮定: 18 × 2 = 36本", "実際との差: 42 - 36 = 6本", "亀の数: 6 ÷ 2 = 3匹", "鶴の数: 18 - 3 = 15匹"], explanation: "鶴亀算の定番の解き方は「全部鶴だったと仮定する」ことです。全部鶴なら足の合計は18×2=36本になるはずですが、実際は42本なのでその差は亀が混じっている分です。亀1匹につき鶴より足が2本多いので、差を2で割ると亀の数が分かります。" },
  { id: "ntt_math_0130", subject: "math", category: "整数", level: 1, type: "input", question: "36と6の最小公倍数を求めなさい。", answer: "36", steps: ["36と6の最大公約数は6", "36 × 6 ÷ 6 = 36"], explanation: "最小公倍数とは、2つの数のどちらの倍数にもなっている整数のうち、最も小さいものです。最大公約数を使うと (最小公倍数)=(36×6)÷(最大公約数) で求められます。" },
  { id: "ntt_math_0131", subject: "math", category: "単位換算", level: 1, type: "input", question: "2.7Lは何mLですか?", answer: "2700mL", steps: ["1L = 1000mL", "2.7 × 1000 = 2700", "よって 2700mL"], explanation: "単位を換算するときは、まず1Lが何mLにあたるかを確認します。1L=1000mLなので、2.7Lはその2.7倍で2700mLになります。" },
  { id: "ntt_math_0132", subject: "math", category: "鶴亀算", level: 5, type: "input", question: "鶴と亀が合わせて24匹おり、足の合計本数は78本である。鶴は何匹いますか?", answer: "9匹", steps: ["全部鶴と仮定: 24 × 2 = 48本", "実際との差: 78 - 48 = 30本", "亀の数: 30 ÷ 2 = 15匹", "鶴の数: 24 - 15 = 9匹"], explanation: "鶴亀算の定番の解き方は「全部鶴だったと仮定する」ことです。全部鶴なら足の合計は24×2=48本になるはずですが、実際は78本なのでその差は亀が混じっている分です。亀1匹につき鶴より足が2本多いので、差を2で割ると亀の数が分かります。" },
  { id: "ntt_math_0133", subject: "math", category: "損益算", level: 5, type: "input", question: "原価800円の商品に15%の利益を見込んで定価をつけた。定価はいくらですか?", answer: "920円", steps: ["利益額: 800 × 15 ÷ 100 = 120", "定価: 800 + 120 = 920"], explanation: "「○%の利益を見込む」ということは、原価に原価の○%を上乗せするということです。定価は「原価×(100+○)/100」で求められます。" },
  { id: "ntt_math_0134", subject: "math", category: "比", level: 2, type: "input", question: "A:B = 3:4 で A=30 のとき、Bの値を求めなさい。", answer: "40", steps: ["30 ÷ 3 = 10倍", "4 × 10 = 40"], explanation: "比が等しいとき、A:B=3:4という関係はどれだけ数が大きくなっても保たれます。AがA=30になったのは、もとの比の3を何倍したかを考えると、B=4にも同じ倍率をかければ求められます。" },
  { id: "ntt_math_0135", subject: "math", category: "割合", level: 1, type: "choice", question: "170人の40%は何人ですか?", choices: ["68人", "73人", "63人", "136人"], answer: "68人", steps: ["40% = 40/100", "170 × 40 ÷ 100 = 68"], explanation: "「○%」は「100人あたり○人の割合」という意味なので、割合を計算するときは百分率を100で割って小数(または分数)に直してからかけます。40%=40/100なので、170×40/100=68人になります。" },
  { id: "ntt_math_0136", subject: "math", category: "速さ・時間・距離", level: 5, type: "input", question: "56km離れた地点からAさんとBさんが同時に向かい合って出発した。Aさんは時速6km、Bさんは時速8kmで進むとき、2人が出会うのは何時間後ですか?", answer: "4時間後", steps: ["2人の速さの和: 6 + 8 = 14km/時", "出会うまでの時間: 56 ÷ 14 = 4時間"], explanation: "2人が向かい合って進むとき、2人の間の距離は「2人の速さの和」の速さで縮まっていきます。したがって、2人の速さを足したものを「合わせた速さ」として、通常の距離÷速さの計算で出会うまでの時間が求められます。" },
  { id: "ntt_math_0137", subject: "math", category: "金額計算", level: 1, type: "input", question: "480円の品物を買うのに2000円出しました。おつりはいくらですか?", answer: "1520円", steps: ["2000 - 480 = 1520"], explanation: "おつりは「支払った金額-品物の値段」で求めます。2000円出して480円の品物を買ったので、2000-480=1520円がおつりになります。" },
  { id: "ntt_math_0138", subject: "math", category: "一次方程式", level: 2, type: "input", question: "2x - 5 = -27 を解きなさい。xの値を答えなさい。", answer: "-11", steps: ["2x = -27 - (-5)", "2x = -22", "x = -22 ÷ 2 = -11"], explanation: "方程式を解くときは、xの項を左辺に、数だけの項を右辺に移項して整理します。「+5」を右辺に移項すると符号が反対の「-5」になります。最後に両辺をxの係数2で割ってxを求めます。" },
  { id: "ntt_math_0139", subject: "math", category: "比例・反比例", level: 2, type: "input", question: "yはxに比例し、x=3のときy=27である。x=8のときのyの値を求めなさい。", answer: "72", steps: ["比例定数 k = 27 ÷ 3 = 9", "y = 9 × 8 = 72"], explanation: "yがxに比例するとき、y=k×xという式が成り立ち、kを比例定数といいます。まず与えられた条件からkを求め、そのkを使って求めたいyの値を計算します。" },
  { id: "ntt_math_0140", subject: "math", category: "平方根", level: 3, type: "input", question: "√4 の値を求めなさい。", answer: "2", steps: ["2 × 2 = 4", "よって √4 = 2"], explanation: "√4(ルート4)とは、2乗すると4になる正の数のことです。2を2乗すると2×2=4になるので、√4=2です。" },
  { id: "ntt_math_0141", subject: "math", category: "平方根", level: 3, type: "input", question: "√81 の値を求めなさい。", answer: "9", steps: ["9 × 9 = 81", "よって √81 = 9"], explanation: "√81(ルート81)とは、2乗すると81になる正の数のことです。9を2乗すると9×9=81になるので、√81=9です。" },
  { id: "ntt_math_0142", subject: "math", category: "割合", level: 1, type: "choice", question: "165人の20%は何人ですか?", choices: ["33人", "38人", "28人", "66人"], answer: "33人", steps: ["20% = 20/100", "165 × 20 ÷ 100 = 33"], explanation: "「○%」は「100人あたり○人の割合」という意味なので、割合を計算するときは百分率を100で割って小数(または分数)に直してからかけます。20%=20/100なので、165×20/100=33人になります。" },
  { id: "ntt_math_0143", subject: "math", category: "百分率", level: 2, type: "input", question: "定価5060円の品物を15%引きで買った。支払う金額はいくらですか?", answer: "4301円", steps: ["100 - 15 = 85(支払う割合は85%)", "5060 × 85 ÷ 100 = 4301"], explanation: "15%引きということは、定価の(100-15)%を支払うことになります。定価に(100-15)/100をかけると、実際に支払う金額が求められます。" },
  { id: "ntt_math_0144", subject: "math", category: "図形", level: 3, type: "input", question: "半径5cmの円の面積を求めなさい。円周率はπとすること。", answer: "25πcm²", steps: ["面積 = 半径 × 半径 × π", "5 × 5 × π = 25π"], explanation: "円の面積は「半径×半径×円周率」で求めます。円周率はπのまま計算してよいので、数値の掛け算だけ行います。" },
  { id: "ntt_math_0145", subject: "math", category: "損益算", level: 5, type: "input", question: "原価2800円の商品に10%の利益を見込んで定価をつけた。定価はいくらですか?", answer: "3080円", steps: ["利益額: 2800 × 10 ÷ 100 = 280", "定価: 2800 + 280 = 3080"], explanation: "「○%の利益を見込む」ということは、原価に原価の○%を上乗せするということです。定価は「原価×(100+○)/100」で求められます。" },
  { id: "ntt_math_0146", subject: "math", category: "比", level: 2, type: "input", question: "A:B = 2:3 で A=22 のとき、Bの値を求めなさい。", answer: "33", steps: ["22 ÷ 2 = 11倍", "3 × 11 = 33"], explanation: "比が等しいとき、A:B=2:3という関係はどれだけ数が大きくなっても保たれます。AがA=22になったのは、もとの比の2を何倍したかを考えると、B=3にも同じ倍率をかければ求められます。" },
  { id: "ntt_math_0147", subject: "math", category: "鶴亀算", level: 5, type: "input", question: "鶴と亀が合わせて34匹おり、足の合計本数は114本である。鶴は何匹いますか?", answer: "11匹", steps: ["全部鶴と仮定: 34 × 2 = 68本", "実際との差: 114 - 68 = 46本", "亀の数: 46 ÷ 2 = 23匹", "鶴の数: 34 - 23 = 11匹"], explanation: "鶴亀算の定番の解き方は「全部鶴だったと仮定する」ことです。全部鶴なら足の合計は34×2=68本になるはずですが、実際は114本なのでその差は亀が混じっている分です。亀1匹につき鶴より足が2本多いので、差を2で割ると亀の数が分かります。" },
  { id: "ntt_math_0148", subject: "math", category: "確率", level: 4, type: "input", question: "大小2つのサイコロを同時に振るとき、目の和が5になる確率を求めなさい。", answer: "1/9", steps: ["目の和が5になる組: (1,4)、(2,3)、(3,2)、(4,1)", "全体は6×6=36通り", "確率 = 4/36 = 1/9"], explanation: "大小2つのサイコロの目の出方は全部で6×6=36通りあります。そのうち目の和が5になる組み合わせを数え上げると4通りあります。" },
  { id: "ntt_math_0149", subject: "math", category: "連立方程式", level: 2, type: "input", question: "連立方程式 2x + 2y = 16, 1x + 5y = 12 を解いたとき、xの値を求めなさい。", answer: "7", steps: ["1つ目の式×5: 10x + 10y = 80", "2つ目の式×2: 2x + 10y = 24", "辺々を引くとyが消える: 8x = 56", "x = 56 ÷ 8 = 7"], explanation: "連立方程式は「加減法」で解くことができます。yの係数をそろえてから2つの式を引き算すると、yが消えてxだけの式になります。1つ目の式を5倍、2つ目の式を2倍すると、どちらもyの係数が10になるので、引き算でyを消去できます。" },
  { id: "ntt_math_0150", subject: "math", category: "比例・反比例", level: 2, type: "input", question: "yはxに比例し、x=1のときy=9である。x=2のときのyの値を求めなさい。", answer: "18", steps: ["比例定数 k = 9 ÷ 1 = 9", "y = 9 × 2 = 18"], explanation: "yがxに比例するとき、y=k×xという式が成り立ち、kを比例定数といいます。まず与えられた条件からkを求め、そのkを使って求めたいyの値を計算します。" },
  { id: "ntt_math_0151", subject: "math", category: "四則演算", level: 1, type: "input", question: "16 + 10 ÷ 5 を計算しなさい。", answer: "18", steps: ["10 ÷ 5 = 2", "16 + 2 = 18"], explanation: "わり算はたし算より先に計算するというルールに従い、まず10÷5を計算してから16を足します。" },
  { id: "ntt_math_0152", subject: "math", category: "割合", level: 5, type: "input", question: "定価3800円の商品を30%値上げした後、さらにそこから20%値引きした。最終的な価格はいくらですか?", answer: "3952円", steps: ["値上げ後: 3800 × (100+30) ÷ 100 = 4940", "値引き後: 4940 × (100-20) ÷ 100 = 3952"], explanation: "割合の変化が2回続く問題では、1回ごとに順番に計算していきます。値上げ後の価格を先に求め、その新しい価格を基準にして値引きを計算する点に注意してください(最初の定価をもとに値引き額を計算するのではありません)。" },
  { id: "ntt_math_0153", subject: "math", category: "比例・反比例", level: 2, type: "input", question: "yはxに比例し、x=2のときy=8である。x=7のときのyの値を求めなさい。", answer: "28", steps: ["比例定数 k = 8 ÷ 2 = 4", "y = 4 × 7 = 28"], explanation: "yがxに比例するとき、y=k×xという式が成り立ち、kを比例定数といいます。まず与えられた条件からkを求め、そのkを使って求めたいyの値を計算します。" },
  { id: "ntt_math_0154", subject: "math", category: "連立方程式", level: 2, type: "input", question: "連立方程式 3x + 1y = 25, 1x + 3y = 11 を解いたとき、xの値を求めなさい。", answer: "8", steps: ["1つ目の式×3: 9x + 3y = 75", "2つ目の式×1: 1x + 3y = 11", "辺々を引くとyが消える: 8x = 64", "x = 64 ÷ 8 = 8"], explanation: "連立方程式は「加減法」で解くことができます。yの係数をそろえてから2つの式を引き算すると、yが消えてxだけの式になります。1つ目の式を3倍、2つ目の式を1倍すると、どちらもyの係数が3になるので、引き算でyを消去できます。" },
  { id: "ntt_math_0155", subject: "math", category: "連立方程式", level: 2, type: "input", question: "連立方程式 1x + 4y = 12, 4x + 3y = 35 を解いたとき、xの値を求めなさい。", answer: "8", steps: ["1つ目の式×3: 3x + 12y = 36", "2つ目の式×4: 16x + 12y = 140", "辺々を引くとyが消える: -13x = -104", "x = -104 ÷ -13 = 8"], explanation: "連立方程式は「加減法」で解くことができます。yの係数をそろえてから2つの式を引き算すると、yが消えてxだけの式になります。1つ目の式を3倍、2つ目の式を4倍すると、どちらもyの係数が12になるので、引き算でyを消去できます。" },
  { id: "ntt_math_0156", subject: "math", category: "百分率", level: 2, type: "input", question: "定価3540円の品物を35%引きで買った。支払う金額はいくらですか?", answer: "2301円", steps: ["100 - 35 = 65(支払う割合は65%)", "3540 × 65 ÷ 100 = 2301"], explanation: "35%引きということは、定価の(100-35)%を支払うことになります。定価に(100-35)/100をかけると、実際に支払う金額が求められます。" },
  { id: "ntt_math_0157", subject: "math", category: "比", level: 2, type: "input", question: "A:B = 5:8 で A=50 のとき、Bの値を求めなさい。", answer: "80", steps: ["50 ÷ 5 = 10倍", "8 × 10 = 80"], explanation: "比が等しいとき、A:B=5:8という関係はどれだけ数が大きくなっても保たれます。AがA=50になったのは、もとの比の5を何倍したかを考えると、B=8にも同じ倍率をかければ求められます。" },
  { id: "ntt_math_0158", subject: "math", category: "図形", level: 3, type: "input", question: "縦11cm、横4cmの長方形の面積を求めなさい。", answer: "44cm²", steps: ["面積 = 縦 × 横", "11 × 4 = 44"], explanation: "長方形の面積は「縦×横」で求めます。" },
  { id: "ntt_math_0159", subject: "math", category: "比例・反比例", level: 2, type: "input", question: "yはxに比例し、x=2のときy=10である。x=3のときのyの値を求めなさい。", answer: "15", steps: ["比例定数 k = 10 ÷ 2 = 5", "y = 5 × 3 = 15"], explanation: "yがxに比例するとき、y=k×xという式が成り立ち、kを比例定数といいます。まず与えられた条件からkを求め、そのkを使って求めたいyの値を計算します。" },
  { id: "ntt_math_0160", subject: "math", category: "速さ・時間・距離", level: 2, type: "input", question: "75kmの道のりを時速75kmで進むと何時間かかりますか?", answer: "1時間", steps: ["時間 = 距離 ÷ 速さ", "75 ÷ 75 = 1"], explanation: "「時間=距離÷速さ」という公式を使います。「距離=速さ×時間」の式を時間について解いた形です。" },
  { id: "ntt_math_0161", subject: "math", category: "整数", level: 1, type: "input", question: "14と18の最大公約数を求めなさい。", answer: "2", steps: ["14を割り切れる数、18を割り切れる数をそれぞれ書き出す", "共通する約数のうち最大のものが2"], explanation: "最大公約数とは、2つの数を共に割り切ることができる整数のうち、最も大きいものです。14の約数と18の約数を比べると、共通する最大の約数は2です。" },
  { id: "ntt_math_0162", subject: "math", category: "平方根", level: 3, type: "input", question: "√25 の値を求めなさい。", answer: "5", steps: ["5 × 5 = 25", "よって √25 = 5"], explanation: "√25(ルート25)とは、2乗すると25になる正の数のことです。5を2乗すると5×5=25になるので、√25=5です。" },
  { id: "ntt_math_0163", subject: "math", category: "図形", level: 3, type: "input", question: "直角三角形の直角をはさむ2辺の長さが9cmと12cmのとき、斜辺の長さを求めなさい。", answer: "15cm", steps: ["9² + 12² = 81 + 144 = 225", "√225 = 15"], explanation: "直角三角形では「(斜辺)²=(辺1)²+(辺2)²」という三平方の定理(ピタゴラスの定理)が成り立ちます。2辺の2乗の和を求めてから平方根をとると斜辺の長さが分かります。" },
  { id: "ntt_math_0164", subject: "math", category: "比例・反比例", level: 2, type: "input", question: "yはxに比例し、x=8のときy=96である。x=2のときのyの値を求めなさい。", answer: "24", steps: ["比例定数 k = 96 ÷ 8 = 12", "y = 12 × 2 = 24"], explanation: "yがxに比例するとき、y=k×xという式が成り立ち、kを比例定数といいます。まず与えられた条件からkを求め、そのkを使って求めたいyの値を計算します。" },
  { id: "ntt_math_0165", subject: "math", category: "平方根", level: 3, type: "input", question: "√150 を最も簡単な形(a√b)に変形したとき、根号の外に出る数(a)を求めなさい。", answer: "5", steps: ["150 を素因数分解して 5² × 6 の形にする", "√(5² × 6) = 5√6"], explanation: "根号の中に同じ数の2乗の形(平方数)が含まれているとき、その数は根号の外に出すことができます。150=5²×6と分解できるので、5²の部分が根号の外に出て5√6になります。" },
  { id: "ntt_math_0166", subject: "math", category: "正負の数", level: 1, type: "input", question: "(6) + (12) を計算しなさい。", answer: "18", steps: ["(6) + (12) = 18"], explanation: "正負の数のたし算では、符号が同じ数どうしは絶対値を足して同じ符号をつけ、符号が異なる数どうしは絶対値の差をとって絶対値の大きい方の符号をつけます。(6)+(12)=18になります。" },
  { id: "ntt_math_0167", subject: "math", category: "場合の数", level: 4, type: "input", question: "異なる7個から3個を選ぶ方法(組み合わせ)は何通りありますか?", answer: "35通り", steps: ["7!/(3!×4!) を計算する", "= 35通り"], explanation: "順序を区別しない「組み合わせ」は、まず順列(並べる場合の数)を求めてから、選んだ3個を並べ替える3!通りで割ることで求められます。" },
  { id: "ntt_math_0168", subject: "math", category: "損益算", level: 5, type: "input", question: "原価8300円の商品に10%の利益を見込んで定価をつけた。定価はいくらですか?", answer: "9130円", steps: ["利益額: 8300 × 10 ÷ 100 = 830", "定価: 8300 + 830 = 9130"], explanation: "「○%の利益を見込む」ということは、原価に原価の○%を上乗せするということです。定価は「原価×(100+○)/100」で求められます。" },
  { id: "ntt_math_0169", subject: "math", category: "仕事算", level: 5, type: "input", question: "ある作業をAさん1人で行うと3日、Bさん1人で行うと6日かかる。2人で一緒に行うと何日で終わりますか?", answer: "2日", steps: ["Aさんの1日の仕事量: 1/3、Bさんの1日の仕事量: 1/6", "2人合わせた1日の仕事量: 1/3 + 1/6 = 9/18", "かかる日数 = 1 ÷ (9/18) = 18/9 = 2日"], explanation: "仕事全体の量を1とすると、Aさんは1日に1/3、Bさんは1日に1/6の仕事をこなします。2人が一緒に働くと1日あたりの仕事量はその合計になるので、全体の1をその合計で割ると完成にかかる日数が求められます。" },
  { id: "ntt_math_0170", subject: "math", category: "比", level: 2, type: "input", question: "A:B = 5:9 で A=25 のとき、Bの値を求めなさい。", answer: "45", steps: ["25 ÷ 5 = 5倍", "9 × 5 = 45"], explanation: "比が等しいとき、A:B=5:9という関係はどれだけ数が大きくなっても保たれます。AがA=25になったのは、もとの比の5を何倍したかを考えると、B=9にも同じ倍率をかければ求められます。" },
  { id: "ntt_math_0171", subject: "math", category: "比例・反比例", level: 2, type: "input", question: "yはxに比例し、x=3のときy=12である。x=4のときのyの値を求めなさい。", answer: "16", steps: ["比例定数 k = 12 ÷ 3 = 4", "y = 4 × 4 = 16"], explanation: "yがxに比例するとき、y=k×xという式が成り立ち、kを比例定数といいます。まず与えられた条件からkを求め、そのkを使って求めたいyの値を計算します。" },
  { id: "ntt_math_0172", subject: "math", category: "四則演算", level: 1, type: "input", question: "14 + 10 × 16 を計算しなさい。", answer: "174", steps: ["10 × 16 = 160", "14 + 160 = 174"], explanation: "計算の順序のルールとして、かけ算・わり算はたし算・ひき算より先に計算します。まず10×16を計算してから14を足します。" },
  { id: "ntt_math_0173", subject: "math", category: "百分率", level: 2, type: "input", question: "定価1680円の品物を20%引きで買った。支払う金額はいくらですか?", answer: "1344円", steps: ["100 - 20 = 80(支払う割合は80%)", "1680 × 80 ÷ 100 = 1344"], explanation: "20%引きということは、定価の(100-20)%を支払うことになります。定価に(100-20)/100をかけると、実際に支払う金額が求められます。" },
  { id: "ntt_math_0174", subject: "math", category: "速さ・時間・距離", level: 2, type: "input", question: "12kmの道のりを時速3kmで進むと何時間かかりますか?", answer: "4時間", steps: ["時間 = 距離 ÷ 速さ", "12 ÷ 3 = 4"], explanation: "「時間=距離÷速さ」という公式を使います。「距離=速さ×時間」の式を時間について解いた形です。" },
  { id: "ntt_math_0175", subject: "math", category: "仕事算", level: 5, type: "input", question: "ある作業をAさん1人で行うと5日、Bさん1人で行うと20日かかる。2人で一緒に行うと何日で終わりますか?", answer: "4日", steps: ["Aさんの1日の仕事量: 1/5、Bさんの1日の仕事量: 1/20", "2人合わせた1日の仕事量: 1/5 + 1/20 = 25/100", "かかる日数 = 1 ÷ (25/100) = 100/25 = 4日"], explanation: "仕事全体の量を1とすると、Aさんは1日に1/5、Bさんは1日に1/20の仕事をこなします。2人が一緒に働くと1日あたりの仕事量はその合計になるので、全体の1をその合計で割ると完成にかかる日数が求められます。" },
  { id: "ntt_math_0176", subject: "math", category: "平方根", level: 3, type: "input", question: "√108 を最も簡単な形(a√b)に変形したとき、根号の外に出る数(a)を求めなさい。", answer: "6", steps: ["108 を素因数分解して 6² × 3 の形にする", "√(6² × 3) = 6√3"], explanation: "根号の中に同じ数の2乗の形(平方数)が含まれているとき、その数は根号の外に出すことができます。108=6²×3と分解できるので、6²の部分が根号の外に出て6√3になります。" },
  { id: "ntt_math_0177", subject: "math", category: "百分率", level: 2, type: "input", question: "定価7020円の品物を40%引きで買った。支払う金額はいくらですか?", answer: "4212円", steps: ["100 - 40 = 60(支払う割合は60%)", "7020 × 60 ÷ 100 = 4212"], explanation: "40%引きということは、定価の(100-40)%を支払うことになります。定価に(100-40)/100をかけると、実際に支払う金額が求められます。" },
  { id: "ntt_math_0178", subject: "math", category: "小数", level: 1, type: "input", question: "1.7 × 9 を計算しなさい。", answer: "15.3", steps: ["1.7 × 9 = 15.3"], explanation: "小数×整数は、いったん小数点を無視して整数どうしのかけ算をしてから、あとで小数点の位置を戻すと計算しやすくなります。1.7×9=15.3になります。" },
  { id: "ntt_math_0179", subject: "math", category: "確率", level: 4, type: "input", question: "大小2つのサイコロを同時に振るとき、目の和が9になる確率を求めなさい。", answer: "1/9", steps: ["目の和が9になる組: (3,6)、(4,5)、(5,4)、(6,3)", "全体は6×6=36通り", "確率 = 4/36 = 1/9"], explanation: "大小2つのサイコロの目の出方は全部で6×6=36通りあります。そのうち目の和が9になる組み合わせを数え上げると4通りあります。" },
  { id: "ntt_math_0180", subject: "math", category: "速さ・時間・距離", level: 2, type: "input", question: "117kmの道のりを時速39kmで進むと何時間かかりますか?", answer: "3時間", steps: ["時間 = 距離 ÷ 速さ", "117 ÷ 39 = 3"], explanation: "「時間=距離÷速さ」という公式を使います。「距離=速さ×時間」の式を時間について解いた形です。" },
  { id: "ntt_math_0181", subject: "math", category: "単位換算", level: 1, type: "input", question: "18.5mは何cmですか?", answer: "1850cm", steps: ["1m = 100cm", "18.5 × 100 = 1850", "よって 1850cm"], explanation: "単位を換算するときは、まず1mが何cmにあたるかを確認します。1m=100cmなので、18.5mはその18.5倍で1850cmになります。" },
  { id: "ntt_math_0182", subject: "math", category: "速さ・時間・距離", level: 5, type: "input", question: "36km離れた地点からAさんとBさんが同時に向かい合って出発した。Aさんは時速5km、Bさんは時速7kmで進むとき、2人が出会うのは何時間後ですか?", answer: "3時間後", steps: ["2人の速さの和: 5 + 7 = 12km/時", "出会うまでの時間: 36 ÷ 12 = 3時間"], explanation: "2人が向かい合って進むとき、2人の間の距離は「2人の速さの和」の速さで縮まっていきます。したがって、2人の速さを足したものを「合わせた速さ」として、通常の距離÷速さの計算で出会うまでの時間が求められます。" },
  { id: "ntt_math_0183", subject: "math", category: "分数", level: 1, type: "input", question: "7/9 + 1/5 を計算しなさい(答えは既約分数で)。", answer: "44/45", steps: ["分母を45にそろえる(通分)", "分子どうしを足す", "約分すると 44/45"], explanation: "分母の違う分数をたすときは、まず通分して分母をそろえる必要があります。9と5の最小公倍数45に通分してから分子どうしを足し、最後に約分すると44/45になります。" },
  { id: "ntt_math_0184", subject: "math", category: "平均", level: 1, type: "input", question: "4個の数 68、72、66、82 の平均を求めなさい。", answer: "72", steps: ["68+72+66+82 = 288", "288 ÷ 4 = 72"], explanation: "平均とは、いくつかの数を均等にならしたときの値のことで、「合計÷個数」で求めます。まずすべての数を足し合わせ、その合計を個数で割ります。" },
  { id: "ntt_math_0185", subject: "math", category: "損益算", level: 5, type: "input", question: "原価8200円の商品に25%の利益を見込んで定価をつけた。定価はいくらですか?", answer: "10250円", steps: ["利益額: 8200 × 25 ÷ 100 = 2050", "定価: 8200 + 2050 = 10250"], explanation: "「○%の利益を見込む」ということは、原価に原価の○%を上乗せするということです。定価は「原価×(100+○)/100」で求められます。" },
  { id: "ntt_math_0186", subject: "math", category: "速さ・時間・距離", level: 2, type: "input", question: "9kmの道のりを3時間で進むと、時速は何kmですか?", answer: "時速3km", steps: ["速さ = 距離 ÷ 時間", "9 ÷ 3 = 3"], explanation: "「速さ=距離÷時間」という公式を使います。1時間あたりに進む距離を求めることになります。" },
  { id: "ntt_math_0187", subject: "math", category: "仕事算", level: 5, type: "input", question: "ある作業をAさん1人で行うと8日、Bさん1人で行うと24日かかる。2人で一緒に行うと何日で終わりますか?", answer: "6日", steps: ["Aさんの1日の仕事量: 1/8、Bさんの1日の仕事量: 1/24", "2人合わせた1日の仕事量: 1/8 + 1/24 = 32/192", "かかる日数 = 1 ÷ (32/192) = 192/32 = 6日"], explanation: "仕事全体の量を1とすると、Aさんは1日に1/8、Bさんは1日に1/24の仕事をこなします。2人が一緒に働くと1日あたりの仕事量はその合計になるので、全体の1をその合計で割ると完成にかかる日数が求められます。" },
  { id: "ntt_math_0188", subject: "math", category: "比例・反比例", level: 2, type: "input", question: "yはxに比例し、x=6のときy=18である。x=1のときのyの値を求めなさい。", answer: "3", steps: ["比例定数 k = 18 ÷ 6 = 3", "y = 3 × 1 = 3"], explanation: "yがxに比例するとき、y=k×xという式が成り立ち、kを比例定数といいます。まず与えられた条件からkを求め、そのkを使って求めたいyの値を計算します。" },
  { id: "ntt_math_0189", subject: "math", category: "二次関数", level: 4, type: "choice", question: "y = x² + 6x + 10 の頂点の座標を求めなさい。", choices: ["(-3, 1)", "(-2, 1)", "(-3, 2)", "(3, 1)"], answer: "(-3, 1)", steps: ["y = x² + 6x + 10 を平方完成する", "y = (x - (-3))² + 1", "頂点は (-3, 1)"], explanation: "二次関数の頂点を求めるには「平方完成」という変形を行い、y=(x-p)²+qの形にします。この形になれば、頂点の座標は(p, q)であるとすぐに分かります。" },
  { id: "ntt_math_0190", subject: "math", category: "速さ・時間・距離", level: 5, type: "input", question: "48km離れた地点からAさんとBさんが同時に向かい合って出発した。Aさんは時速9km、Bさんは時速3kmで進むとき、2人が出会うのは何時間後ですか?", answer: "4時間後", steps: ["2人の速さの和: 9 + 3 = 12km/時", "出会うまでの時間: 48 ÷ 12 = 4時間"], explanation: "2人が向かい合って進むとき、2人の間の距離は「2人の速さの和」の速さで縮まっていきます。したがって、2人の速さを足したものを「合わせた速さ」として、通常の距離÷速さの計算で出会うまでの時間が求められます。" },
  { id: "ntt_math_0191", subject: "math", category: "図形と計量", level: 4, type: "choice", question: "sin45° の値を求めなさい。", choices: ["√2/2", "0", "1", "1/2"], answer: "√2/2", explanation: "sin45°=√2/2という三角比の基本値です。45°の直角二等辺三角形の辺の比(1:1:√2)から求められます。" },
  { id: "ntt_math_0192", subject: "math", category: "場合の数", level: 4, type: "input", question: "異なる9個から5個を選んで並べる方法(順列)は何通りありますか?", answer: "15120通り", steps: ["9 × 8 × 7 × 6 × 5 = 15120"], explanation: "順序を区別して並べる「順列」は、1番目に選べるものが9通り、2番目は残りの8通り、というように1つずつ減らしながらかけ合わせます。" },
  { id: "ntt_math_0193", subject: "math", category: "単位換算", level: 1, type: "input", question: "15.3Lは何mLですか?", answer: "15300mL", steps: ["1L = 1000mL", "15.3 × 1000 = 15300", "よって 15300mL"], explanation: "単位を換算するときは、まず1Lが何mLにあたるかを確認します。1L=1000mLなので、15.3Lはその15.3倍で15300mLになります。" },
  { id: "ntt_math_0194", subject: "math", category: "分数", level: 1, type: "input", question: "7/2 × 3/4 を計算しなさい(答えは既約分数で)。", answer: "21/8", steps: ["分子どうし・分母どうしをかける", "約分すると 21/8"], explanation: "分数どうしのかけ算は、通分せずにそのまま分子は分子どうし、分母は分母どうしをかけます。かけた後に約分すると21/8になります。" },
  { id: "ntt_math_0195", subject: "math", category: "鶴亀算", level: 5, type: "input", question: "鶴と亀が合わせて34匹おり、足の合計本数は106本である。鶴は何匹いますか?", answer: "15匹", steps: ["全部鶴と仮定: 34 × 2 = 68本", "実際との差: 106 - 68 = 38本", "亀の数: 38 ÷ 2 = 19匹", "鶴の数: 34 - 19 = 15匹"], explanation: "鶴亀算の定番の解き方は「全部鶴だったと仮定する」ことです。全部鶴なら足の合計は34×2=68本になるはずですが、実際は106本なのでその差は亀が混じっている分です。亀1匹につき鶴より足が2本多いので、差を2で割ると亀の数が分かります。" },
  { id: "ntt_math_0196", subject: "math", category: "割合", level: 5, type: "input", question: "定価6000円の商品を30%値上げした後、さらにそこから25%値引きした。最終的な価格はいくらですか?", answer: "5850円", steps: ["値上げ後: 6000 × (100+30) ÷ 100 = 7800", "値引き後: 7800 × (100-25) ÷ 100 = 5850"], explanation: "割合の変化が2回続く問題では、1回ごとに順番に計算していきます。値上げ後の価格を先に求め、その新しい価格を基準にして値引きを計算する点に注意してください(最初の定価をもとに値引き額を計算するのではありません)。" },
  { id: "ntt_math_0197", subject: "math", category: "平均", level: 1, type: "input", question: "4個の数 48、40、54、50 の平均を求めなさい。", answer: "48", steps: ["48+40+54+50 = 192", "192 ÷ 4 = 48"], explanation: "平均とは、いくつかの数を均等にならしたときの値のことで、「合計÷個数」で求めます。まずすべての数を足し合わせ、その合計を個数で割ります。" },
  { id: "ntt_math_0198", subject: "math", category: "平方根", level: 3, type: "input", question: "√64 の値を求めなさい。", answer: "8", steps: ["8 × 8 = 64", "よって √64 = 8"], explanation: "√64(ルート64)とは、2乗すると64になる正の数のことです。8を2乗すると8×8=64になるので、√64=8です。" },
  { id: "ntt_math_0199", subject: "math", category: "二次関数", level: 4, type: "choice", question: "y = x² - 6x + 1 の頂点の座標を求めなさい。", choices: ["(3, -8)", "(4, -8)", "(3, -7)", "(-3, -8)"], answer: "(3, -8)", steps: ["y = x² - 6x + 1 を平方完成する", "y = (x - (3))² + -8", "頂点は (3, -8)"], explanation: "二次関数の頂点を求めるには「平方完成」という変形を行い、y=(x-p)²+qの形にします。この形になれば、頂点の座標は(p, q)であるとすぐに分かります。" },
  { id: "ntt_math_0200", subject: "math", category: "小数", level: 1, type: "input", question: "26.2 - 20.3 を計算しなさい。", answer: "5.9", steps: ["小数点の位置をそろえる", "26.2 - 20.3 = 5.9"], explanation: "小数のひき算も、小数点の位置をそろえて筆算します。位をそろえて計算すると26.2-20.3=5.9になります。" },
  { id: "ntt_math_0201", subject: "math", category: "割合", level: 1, type: "choice", question: "60人の25%は何人ですか?", choices: ["15人", "20人", "10人", "30人"], answer: "15人", steps: ["25% = 25/100", "60 × 25 ÷ 100 = 15"], explanation: "「○%」は「100人あたり○人の割合」という意味なので、割合を計算するときは百分率を100で割って小数(または分数)に直してからかけます。25%=25/100なので、60×25/100=15人になります。" },
  { id: "ntt_math_0202", subject: "math", category: "割合", level: 1, type: "choice", question: "115人の20%は何人ですか?", choices: ["23人", "28人", "18人", "46人"], answer: "23人", steps: ["20% = 20/100", "115 × 20 ÷ 100 = 23"], explanation: "「○%」は「100人あたり○人の割合」という意味なので、割合を計算するときは百分率を100で割って小数(または分数)に直してからかけます。20%=20/100なので、115×20/100=23人になります。" },
  { id: "ntt_math_0203", subject: "math", category: "消費税", level: 2, type: "input", question: "税抜き9520円の商品に消費税10%がかかるとき、税込み価格はいくらですか?", answer: "10472円", steps: ["消費税額: 9520 × 10 ÷ 100 = 952", "税込み価格: 9520 + 952 = 10472"], explanation: "税込み価格は「税抜き価格+消費税額」で求めます。消費税額は税抜き価格に税率(%)をかけて100で割ることで計算できます。" },
  { id: "ntt_math_0204", subject: "math", category: "比", level: 2, type: "input", question: "A:B = 8:3 で A=72 のとき、Bの値を求めなさい。", answer: "27", steps: ["72 ÷ 8 = 9倍", "3 × 9 = 27"], explanation: "比が等しいとき、A:B=8:3という関係はどれだけ数が大きくなっても保たれます。AがA=72になったのは、もとの比の8を何倍したかを考えると、B=3にも同じ倍率をかければ求められます。" },
  { id: "ntt_math_0205", subject: "math", category: "正負の数", level: 1, type: "input", question: "(-19) - (17) を計算しなさい。", answer: "-36", steps: ["(-19) - (17) = (-19) + (-17)", "= -36"], explanation: "正負の数のひき算は、引く数の符号を反対にしてたし算に直すと考えやすくなります。(-19)-(17)=(-19)+(-17)=-36になります。" },
  { id: "ntt_math_0206", subject: "math", category: "金額計算", level: 1, type: "input", question: "320円の品物を買うのに5000円出しました。おつりはいくらですか?", answer: "4680円", steps: ["5000 - 320 = 4680"], explanation: "おつりは「支払った金額-品物の値段」で求めます。5000円出して320円の品物を買ったので、5000-320=4680円がおつりになります。" },
  { id: "ntt_math_0207", subject: "math", category: "確率", level: 4, type: "input", question: "大小2つのサイコロを同時に振るとき、目の和が12になる確率を求めなさい。", answer: "1/36", steps: ["目の和が12になる組: (6,6)", "全体は6×6=36通り", "確率 = 1/36 = 1/36"], explanation: "大小2つのサイコロの目の出方は全部で6×6=36通りあります。そのうち目の和が12になる組み合わせを数え上げると1通りあります。" },
  { id: "ntt_math_0208", subject: "math", category: "四則演算", level: 1, type: "input", question: "20 + 16 ÷ 4 を計算しなさい。", answer: "24", steps: ["16 ÷ 4 = 4", "20 + 4 = 24"], explanation: "わり算はたし算より先に計算するというルールに従い、まず16÷4を計算してから20を足します。" },
  { id: "ntt_math_0209", subject: "math", category: "連立方程式", level: 2, type: "input", question: "連立方程式 2x + 5y = 36, 3x + 2y = 21 を解いたとき、xの値を求めなさい。", answer: "3", steps: ["1つ目の式×2: 4x + 10y = 72", "2つ目の式×5: 15x + 10y = 105", "辺々を引くとyが消える: -11x = -33", "x = -33 ÷ -11 = 3"], explanation: "連立方程式は「加減法」で解くことができます。yの係数をそろえてから2つの式を引き算すると、yが消えてxだけの式になります。1つ目の式を2倍、2つ目の式を5倍すると、どちらもyの係数が10になるので、引き算でyを消去できます。" },
  { id: "ntt_math_0210", subject: "math", category: "二次関数", level: 4, type: "choice", question: "y = x² + 2x - 9 の頂点の座標を求めなさい。", choices: ["(-1, -10)", "(0, -10)", "(-1, -9)", "(1, -10)"], answer: "(-1, -10)", steps: ["y = x² + 2x - 9 を平方完成する", "y = (x - (-1))² + -10", "頂点は (-1, -10)"], explanation: "二次関数の頂点を求めるには「平方完成」という変形を行い、y=(x-p)²+qの形にします。この形になれば、頂点の座標は(p, q)であるとすぐに分かります。" },
  { id: "ntt_math_0211", subject: "math", category: "場合の数", level: 4, type: "input", question: "異なる8個から4個を選んで並べる方法(順列)は何通りありますか?", answer: "1680通り", steps: ["8 × 7 × 6 × 5 = 1680"], explanation: "順序を区別して並べる「順列」は、1番目に選べるものが8通り、2番目は残りの7通り、というように1つずつ減らしながらかけ合わせます。" },
  { id: "ntt_math_0212", subject: "math", category: "割合", level: 5, type: "input", question: "定価8350円の商品を20%値上げした後、さらにそこから10%値引きした。最終的な価格はいくらですか?", answer: "9018円", steps: ["値上げ後: 8350 × (100+20) ÷ 100 = 10020", "値引き後: 10020 × (100-10) ÷ 100 = 9018"], explanation: "割合の変化が2回続く問題では、1回ごとに順番に計算していきます。値上げ後の価格を先に求め、その新しい価格を基準にして値引きを計算する点に注意してください(最初の定価をもとに値引き額を計算するのではありません)。" },
  { id: "ntt_math_0213", subject: "math", category: "二次関数", level: 4, type: "choice", question: "y = x² - 4x + 2 の頂点の座標を求めなさい。", choices: ["(2, -2)", "(3, -2)", "(2, -1)", "(-2, -2)"], answer: "(2, -2)", steps: ["y = x² - 4x + 2 を平方完成する", "y = (x - (2))² + -2", "頂点は (2, -2)"], explanation: "二次関数の頂点を求めるには「平方完成」という変形を行い、y=(x-p)²+qの形にします。この形になれば、頂点の座標は(p, q)であるとすぐに分かります。" },
  { id: "ntt_math_0214", subject: "math", category: "確率", level: 3, type: "input", question: "サイコロを1回振って、4以下の目が出る確率を求めなさい。", answer: "2/3", steps: ["4以下の目: 1, 2, 3, 4(4通り)", "全体は6通り", "確率 = 4/6 = 2/3"], explanation: "確率は「求める場合の数÷すべての場合の数」で計算します。サイコロの目の出方は全部で6通りあり、そのうち4以下の目は4通りあります。" },
  { id: "ntt_math_0215", subject: "math", category: "図形と計量", level: 4, type: "choice", question: "cos60° の値を求めなさい。", choices: ["1/2", "0", "1", "√2/2"], answer: "1/2", explanation: "cos60°=1/2という三角比の基本値です。30°-60°-90°の直角三角形の辺の比から求められます。cos60°はsin30°と同じ値になります。" },
  { id: "ntt_math_0216", subject: "math", category: "場合の数", level: 4, type: "input", question: "異なる4個から1個を選ぶ方法(組み合わせ)は何通りありますか?", answer: "4通り", steps: ["4!/(1!×3!) を計算する", "= 4通り"], explanation: "順序を区別しない「組み合わせ」は、まず順列(並べる場合の数)を求めてから、選んだ1個を並べ替える1!通りで割ることで求められます。" },
  { id: "ntt_math_0217", subject: "math", category: "二次関数", level: 4, type: "choice", question: "y = x² - 16x + 58 の頂点の座標を求めなさい。", choices: ["(8, -6)", "(9, -6)", "(8, -5)", "(-8, -6)"], answer: "(8, -6)", steps: ["y = x² - 16x + 58 を平方完成する", "y = (x - (8))² + -6", "頂点は (8, -6)"], explanation: "二次関数の頂点を求めるには「平方完成」という変形を行い、y=(x-p)²+qの形にします。この形になれば、頂点の座標は(p, q)であるとすぐに分かります。" },
  { id: "ntt_math_0218", subject: "math", category: "確率", level: 3, type: "input", question: "赤玉3個、白玉1個が入った袋から1個取り出すとき、赤玉が出る確率を求めなさい。", answer: "3/4", steps: ["全体の玉の数: 3 + 1 = 4個", "確率 = 3/4 = 3/4"], explanation: "確率は「求める場合の数÷すべての場合の数」で計算します。袋の中の玉は全部で4個あり、そのうち赤玉は3個です。" },
  { id: "ntt_math_0219", subject: "math", category: "単位換算", level: 1, type: "input", question: "5.5Lは何mLですか?", answer: "5500mL", steps: ["1L = 1000mL", "5.5 × 1000 = 5500", "よって 5500mL"], explanation: "単位を換算するときは、まず1Lが何mLにあたるかを確認します。1L=1000mLなので、5.5Lはその5.5倍で5500mLになります。" },
  { id: "ntt_math_0220", subject: "math", category: "平方根", level: 3, type: "input", question: "√289 の値を求めなさい。", answer: "17", steps: ["17 × 17 = 289", "よって √289 = 17"], explanation: "√289(ルート289)とは、2乗すると289になる正の数のことです。17を2乗すると17×17=289になるので、√289=17です。" },
  { id: "ntt_math_0221", subject: "math", category: "図形と計量", level: 4, type: "choice", question: "cos45° の値を求めなさい。", choices: ["√2/2", "0", "1", "1/2"], answer: "√2/2", explanation: "cos45°=√2/2という三角比の基本値です。45°の直角二等辺三角形の辺の比から求められます。cos45°はsin45°と同じ値になります。" },
  { id: "ntt_math_0222", subject: "math", category: "図形", level: 3, type: "input", question: "縦19cm、横4cmの長方形の周りの長さを求めなさい。", answer: "46cm", steps: ["周りの長さ = (縦 + 横) × 2", "(19 + 4) × 2 = 46"], explanation: "長方形の周りの長さは、縦と横をそれぞれ2辺ずつ持つので「(縦+横)×2」で求めます。" },
  { id: "ntt_math_0223", subject: "math", category: "消費税", level: 2, type: "input", question: "税抜き2920円の商品に消費税10%がかかるとき、税込み価格はいくらですか?", answer: "3212円", steps: ["消費税額: 2920 × 10 ÷ 100 = 292", "税込み価格: 2920 + 292 = 3212"], explanation: "税込み価格は「税抜き価格+消費税額」で求めます。消費税額は税抜き価格に税率(%)をかけて100で割ることで計算できます。" },
  { id: "ntt_math_0224", subject: "math", category: "速さ・時間・距離", level: 2, type: "input", question: "69kmの道のりを1時間で進むと、時速は何kmですか?", answer: "時速69km", steps: ["速さ = 距離 ÷ 時間", "69 ÷ 1 = 69"], explanation: "「速さ=距離÷時間」という公式を使います。1時間あたりに進む距離を求めることになります。" },
  { id: "ntt_math_0225", subject: "math", category: "二次関数", level: 4, type: "choice", question: "y = x² + 6x + 23 の頂点の座標を求めなさい。", choices: ["(-3, 14)", "(-2, 14)", "(-3, 15)", "(3, 14)"], answer: "(-3, 14)", steps: ["y = x² + 6x + 23 を平方完成する", "y = (x - (-3))² + 14", "頂点は (-3, 14)"], explanation: "二次関数の頂点を求めるには「平方完成」という変形を行い、y=(x-p)²+qの形にします。この形になれば、頂点の座標は(p, q)であるとすぐに分かります。" },
  { id: "ntt_math_0226", subject: "math", category: "平方根", level: 3, type: "input", question: "√9 の値を求めなさい。", answer: "3", steps: ["3 × 3 = 9", "よって √9 = 3"], explanation: "√9(ルート9)とは、2乗すると9になる正の数のことです。3を2乗すると3×3=9になるので、√9=3です。" },
  { id: "ntt_math_0227", subject: "math", category: "一次方程式", level: 2, type: "input", question: "2x + 15 = 31 を解きなさい。xの値を答えなさい。", answer: "8", steps: ["2x = 31 - (15)", "2x = 16", "x = 16 ÷ 2 = 8"], explanation: "方程式を解くときは、xの項を左辺に、数だけの項を右辺に移項して整理します。「+15」を右辺に移項すると符号が反対の「-15」になります。最後に両辺をxの係数2で割ってxを求めます。" },
  { id: "ntt_math_0228", subject: "math", category: "連立方程式", level: 2, type: "input", question: "連立方程式 4x + 3y = 75, 5x + 4y = 96 を解いたとき、xの値を求めなさい。", answer: "12", steps: ["1つ目の式×4: 16x + 12y = 300", "2つ目の式×3: 15x + 12y = 288", "辺々を引くとyが消える: 1x = 12", "x = 12 ÷ 1 = 12"], explanation: "連立方程式は「加減法」で解くことができます。yの係数をそろえてから2つの式を引き算すると、yが消えてxだけの式になります。1つ目の式を4倍、2つ目の式を3倍すると、どちらもyの係数が12になるので、引き算でyを消去できます。" },
  { id: "ntt_math_0229", subject: "math", category: "金額計算", level: 1, type: "input", question: "260円の品物を買うのに1000円出しました。おつりはいくらですか?", answer: "740円", steps: ["1000 - 260 = 740"], explanation: "おつりは「支払った金額-品物の値段」で求めます。1000円出して260円の品物を買ったので、1000-260=740円がおつりになります。" },
  { id: "ntt_math_0230", subject: "math", category: "消費税", level: 2, type: "input", question: "税抜き3390円の商品に消費税10%がかかるとき、税込み価格はいくらですか?", answer: "3729円", steps: ["消費税額: 3390 × 10 ÷ 100 = 339", "税込み価格: 3390 + 339 = 3729"], explanation: "税込み価格は「税抜き価格+消費税額」で求めます。消費税額は税抜き価格に税率(%)をかけて100で割ることで計算できます。" },
  { id: "ntt_math_0231", subject: "math", category: "比", level: 2, type: "input", question: "A:B = 7:3 で A=56 のとき、Bの値を求めなさい。", answer: "24", steps: ["56 ÷ 7 = 8倍", "3 × 8 = 24"], explanation: "比が等しいとき、A:B=7:3という関係はどれだけ数が大きくなっても保たれます。AがA=56になったのは、もとの比の7を何倍したかを考えると、B=3にも同じ倍率をかければ求められます。" },
  { id: "ntt_math_0232", subject: "math", category: "金額計算", level: 1, type: "input", question: "90円の品物を買うのに2000円出しました。おつりはいくらですか?", answer: "1910円", steps: ["2000 - 90 = 1910"], explanation: "おつりは「支払った金額-品物の値段」で求めます。2000円出して90円の品物を買ったので、2000-90=1910円がおつりになります。" },
  { id: "ntt_math_0233", subject: "math", category: "場合の数", level: 4, type: "input", question: "異なる6個から3個を選ぶ方法(組み合わせ)は何通りありますか?", answer: "20通り", steps: ["6!/(3!×3!) を計算する", "= 20通り"], explanation: "順序を区別しない「組み合わせ」は、まず順列(並べる場合の数)を求めてから、選んだ3個を並べ替える3!通りで割ることで求められます。" },
  { id: "ntt_math_0234", subject: "math", category: "場合の数", level: 4, type: "input", question: "異なる8個から1個を選んで並べる方法(順列)は何通りありますか?", answer: "8通り", steps: ["8 = 8"], explanation: "順序を区別して並べる「順列」は、1番目に選べるものが8通り、2番目は残りの7通り、というように1つずつ減らしながらかけ合わせます。" },
  { id: "ntt_math_0235", subject: "math", category: "平均", level: 1, type: "input", question: "3個の数 70、40、46 の平均を求めなさい。", answer: "52", steps: ["70+40+46 = 156", "156 ÷ 3 = 52"], explanation: "平均とは、いくつかの数を均等にならしたときの値のことで、「合計÷個数」で求めます。まずすべての数を足し合わせ、その合計を個数で割ります。" },
  { id: "ntt_math_0236", subject: "math", category: "小数", level: 1, type: "input", question: "2.1 × 7 を計算しなさい。", answer: "14.7", steps: ["2.1 × 7 = 14.7"], explanation: "小数×整数は、いったん小数点を無視して整数どうしのかけ算をしてから、あとで小数点の位置を戻すと計算しやすくなります。2.1×7=14.7になります。" },
  { id: "ntt_math_0237", subject: "math", category: "分数", level: 1, type: "input", question: "8/7 × 1/6 を計算しなさい(答えは既約分数で)。", answer: "4/21", steps: ["分子どうし・分母どうしをかける", "約分すると 4/21"], explanation: "分数どうしのかけ算は、通分せずにそのまま分子は分子どうし、分母は分母どうしをかけます。かけた後に約分すると4/21になります。" },
  { id: "ntt_math_0238", subject: "math", category: "場合の数", level: 4, type: "input", question: "異なる5個から4個を選ぶ方法(組み合わせ)は何通りありますか?", answer: "5通り", steps: ["5!/(4!×1!) を計算する", "= 5通り"], explanation: "順序を区別しない「組み合わせ」は、まず順列(並べる場合の数)を求めてから、選んだ4個を並べ替える4!通りで割ることで求められます。" },
  { id: "ntt_math_0239", subject: "math", category: "確率", level: 4, type: "input", question: "大小2つのサイコロを同時に振るとき、目の和が11になる確率を求めなさい。", answer: "1/18", steps: ["目の和が11になる組: (5,6)、(6,5)", "全体は6×6=36通り", "確率 = 2/36 = 1/18"], explanation: "大小2つのサイコロの目の出方は全部で6×6=36通りあります。そのうち目の和が11になる組み合わせを数え上げると2通りあります。" },
  { id: "ntt_math_0240", subject: "math", category: "四則演算", level: 1, type: "input", question: "2 + 8 ÷ 4 を計算しなさい。", answer: "4", steps: ["8 ÷ 4 = 2", "2 + 2 = 4"], explanation: "わり算はたし算より先に計算するというルールに従い、まず8÷4を計算してから2を足します。" },
  { id: "ntt_math_0241", subject: "math", category: "比", level: 2, type: "input", question: "A:B = 7:3 で A=21 のとき、Bの値を求めなさい。", answer: "9", steps: ["21 ÷ 7 = 3倍", "3 × 3 = 9"], explanation: "比が等しいとき、A:B=7:3という関係はどれだけ数が大きくなっても保たれます。AがA=21になったのは、もとの比の7を何倍したかを考えると、B=3にも同じ倍率をかければ求められます。" },
  { id: "ntt_math_0242", subject: "math", category: "割合", level: 5, type: "input", question: "定価800円の商品を25%値上げした後、さらにそこから10%値引きした。最終的な価格はいくらですか?", answer: "900円", steps: ["値上げ後: 800 × (100+25) ÷ 100 = 1000", "値引き後: 1000 × (100-10) ÷ 100 = 900"], explanation: "割合の変化が2回続く問題では、1回ごとに順番に計算していきます。値上げ後の価格を先に求め、その新しい価格を基準にして値引きを計算する点に注意してください(最初の定価をもとに値引き額を計算するのではありません)。" },
  { id: "ntt_math_0243", subject: "math", category: "百分率", level: 2, type: "input", question: "定価8300円の品物を10%引きで買った。支払う金額はいくらですか?", answer: "7470円", steps: ["100 - 10 = 90(支払う割合は90%)", "8300 × 90 ÷ 100 = 7470"], explanation: "10%引きということは、定価の(100-10)%を支払うことになります。定価に(100-10)/100をかけると、実際に支払う金額が求められます。" },
  { id: "ntt_math_0244", subject: "math", category: "確率", level: 4, type: "input", question: "大小2つのサイコロを同時に振るとき、目の和が3になる確率を求めなさい。", answer: "1/18", steps: ["目の和が3になる組: (1,2)、(2,1)", "全体は6×6=36通り", "確率 = 2/36 = 1/18"], explanation: "大小2つのサイコロの目の出方は全部で6×6=36通りあります。そのうち目の和が3になる組み合わせを数え上げると2通りあります。" },
  { id: "ntt_math_0245", subject: "math", category: "平均", level: 1, type: "input", question: "4個の数 42、64、92、78 の平均を求めなさい。", answer: "69", steps: ["42+64+92+78 = 276", "276 ÷ 4 = 69"], explanation: "平均とは、いくつかの数を均等にならしたときの値のことで、「合計÷個数」で求めます。まずすべての数を足し合わせ、その合計を個数で割ります。" },
  { id: "ntt_math_0246", subject: "math", category: "小数", level: 1, type: "input", question: "12.9 - 12.3 を計算しなさい。", answer: "0.6", steps: ["小数点の位置をそろえる", "12.9 - 12.3 = 0.6"], explanation: "小数のひき算も、小数点の位置をそろえて筆算します。位をそろえて計算すると12.9-12.3=0.6になります。" },
  { id: "ntt_math_0247", subject: "math", category: "確率", level: 3, type: "input", question: "赤玉8個、白玉7個が入った袋から1個取り出すとき、赤玉が出る確率を求めなさい。", answer: "8/15", steps: ["全体の玉の数: 8 + 7 = 15個", "確率 = 8/15 = 8/15"], explanation: "確率は「求める場合の数÷すべての場合の数」で計算します。袋の中の玉は全部で15個あり、そのうち赤玉は8個です。" },
  { id: "ntt_math_0248", subject: "math", category: "平均", level: 1, type: "input", question: "4個の数 30、52、58、72 の平均を求めなさい。", answer: "53", steps: ["30+52+58+72 = 212", "212 ÷ 4 = 53"], explanation: "平均とは、いくつかの数を均等にならしたときの値のことで、「合計÷個数」で求めます。まずすべての数を足し合わせ、その合計を個数で割ります。" },
  { id: "ntt_math_0249", subject: "math", category: "四則演算", level: 1, type: "input", question: "14 + 12 × 10 を計算しなさい。", answer: "134", steps: ["12 × 10 = 120", "14 + 120 = 134"], explanation: "計算の順序のルールとして、かけ算・わり算はたし算・ひき算より先に計算します。まず12×10を計算してから14を足します。" },
  { id: "ntt_math_0250", subject: "math", category: "確率", level: 4, type: "input", question: "大小2つのサイコロを同時に振るとき、目の和が8になる確率を求めなさい。", answer: "5/36", steps: ["目の和が8になる組: (2,6)、(3,5)、(4,4)、(5,3)、(6,2)", "全体は6×6=36通り", "確率 = 5/36 = 5/36"], explanation: "大小2つのサイコロの目の出方は全部で6×6=36通りあります。そのうち目の和が8になる組み合わせを数え上げると5通りあります。" },
  { id: "ntt_math_0251", subject: "math", category: "二次方程式", level: 3, type: "choice", question: "x² + 10x + 21 = 0 を解きなさい。", choices: ["x=-7, -3", "x=-6, -3", "x=-7, -2", "x=7, 3"], answer: "x=-7, -3", steps: ["かけて21、足して-10になる2数を探す → -7 と -3", "(x-(-7))(x-(-3)) = 0", "x = -7, -3"], explanation: "二次方程式は、左辺を(x-○)(x-△)の形に因数分解できれば、○と△が解になります。かけて21、足して-10になる2つの数を探すと-7と-3が見つかります。" },
  { id: "ntt_math_0252", subject: "math", category: "図形", level: 3, type: "input", question: "縦7cm、横9cm、高さ3cmの直方体の体積を求めなさい。", answer: "189cm³", steps: ["体積 = 縦 × 横 × 高さ", "7 × 9 × 3 = 189"], explanation: "直方体の体積は「縦×横×高さ」で求めます。底面積(縦×横)に高さをかけると考えることもできます。" },
  { id: "ntt_math_0253", subject: "math", category: "仕事算", level: 5, type: "input", question: "ある作業をAさん1人で行うと4日、Bさん1人で行うと12日かかる。2人で一緒に行うと何日で終わりますか?", answer: "3日", steps: ["Aさんの1日の仕事量: 1/4、Bさんの1日の仕事量: 1/12", "2人合わせた1日の仕事量: 1/4 + 1/12 = 16/48", "かかる日数 = 1 ÷ (16/48) = 48/16 = 3日"], explanation: "仕事全体の量を1とすると、Aさんは1日に1/4、Bさんは1日に1/12の仕事をこなします。2人が一緒に働くと1日あたりの仕事量はその合計になるので、全体の1をその合計で割ると完成にかかる日数が求められます。" },
  { id: "ntt_math_0254", subject: "math", category: "確率", level: 3, type: "input", question: "サイコロを1回振って、2以下の目が出る確率を求めなさい。", answer: "1/3", steps: ["2以下の目: 1, 2(2通り)", "全体は6通り", "確率 = 2/6 = 1/3"], explanation: "確率は「求める場合の数÷すべての場合の数」で計算します。サイコロの目の出方は全部で6通りあり、そのうち2以下の目は2通りあります。" },
  { id: "ntt_math_0255", subject: "math", category: "分数", level: 1, type: "input", question: "7/2 - 1 を計算しなさい(答えは既約分数で)。", answer: "5/2", steps: ["分母を2にそろえる(通分)", "分子どうしを引く", "約分すると 5/2"], explanation: "分母の違う分数をひくときも、まず通分して分母をそろえます。2と1の最小公倍数2に通分してから分子どうしを引き、最後に約分すると5/2になります。" },
  { id: "ntt_math_0256", subject: "math", category: "図形", level: 3, type: "input", question: "半径3cmの円の円周を求めなさい。円周率はπとすること。", answer: "6πcm", steps: ["直径 = 3 × 2 = 6", "円周 = 6 × π = 6π"], explanation: "円周は「直径×円周率」で求めます。直径は半径の2倍なので、まず直径を求めてからπをかけます。" },
  { id: "ntt_math_0257", subject: "math", category: "一次方程式", level: 2, type: "input", question: "2x + 23 = 9 を解きなさい。xの値を答えなさい。", answer: "-7", steps: ["2x = 9 - (23)", "2x = -14", "x = -14 ÷ 2 = -7"], explanation: "方程式を解くときは、xの項を左辺に、数だけの項を右辺に移項して整理します。「+23」を右辺に移項すると符号が反対の「-23」になります。最後に両辺をxの係数2で割ってxを求めます。" },
  { id: "ntt_math_0258", subject: "math", category: "四則演算", level: 1, type: "input", question: "6 + 2 × 13 を計算しなさい。", answer: "32", steps: ["2 × 13 = 26", "6 + 26 = 32"], explanation: "計算の順序のルールとして、かけ算・わり算はたし算・ひき算より先に計算します。まず2×13を計算してから6を足します。" },
  { id: "ntt_math_0259", subject: "math", category: "確率", level: 3, type: "input", question: "赤玉1個、白玉2個が入った袋から1個取り出すとき、赤玉が出る確率を求めなさい。", answer: "1/3", steps: ["全体の玉の数: 1 + 2 = 3個", "確率 = 1/3 = 1/3"], explanation: "確率は「求める場合の数÷すべての場合の数」で計算します。袋の中の玉は全部で3個あり、そのうち赤玉は1個です。" },
  { id: "ntt_math_0260", subject: "math", category: "図形と計量", level: 4, type: "choice", question: "cos90° の値を求めなさい。", choices: ["0", "1", "1/2", "√2/2"], answer: "0", explanation: "cos90°=0という三角比の基本値です。90°では単位円上の点のx座標が0になります。" },
  { id: "ntt_math_0261", subject: "math", category: "損益算", level: 5, type: "input", question: "原価1500円の商品に25%の利益を見込んで定価をつけた。定価はいくらですか?", answer: "1875円", steps: ["利益額: 1500 × 25 ÷ 100 = 375", "定価: 1500 + 375 = 1875"], explanation: "「○%の利益を見込む」ということは、原価に原価の○%を上乗せするということです。定価は「原価×(100+○)/100」で求められます。" },
  { id: "ntt_math_0262", subject: "math", category: "場合の数", level: 4, type: "input", question: "異なる9個から5個を選ぶ方法(組み合わせ)は何通りありますか?", answer: "126通り", steps: ["9!/(5!×4!) を計算する", "= 126通り"], explanation: "順序を区別しない「組み合わせ」は、まず順列(並べる場合の数)を求めてから、選んだ5個を並べ替える5!通りで割ることで求められます。" },
  { id: "ntt_math_0263", subject: "math", category: "平方根", level: 3, type: "input", question: "√50 を最も簡単な形(a√b)に変形したとき、根号の外に出る数(a)を求めなさい。", answer: "5", steps: ["50 を素因数分解して 5² × 2 の形にする", "√(5² × 2) = 5√2"], explanation: "根号の中に同じ数の2乗の形(平方数)が含まれているとき、その数は根号の外に出すことができます。50=5²×2と分解できるので、5²の部分が根号の外に出て5√2になります。" },
  { id: "ntt_math_0264", subject: "math", category: "場合の数", level: 4, type: "input", question: "異なる8個から3個を選んで並べる方法(順列)は何通りありますか?", answer: "336通り", steps: ["8 × 7 × 6 = 336"], explanation: "順序を区別して並べる「順列」は、1番目に選べるものが8通り、2番目は残りの7通り、というように1つずつ減らしながらかけ合わせます。" },
  { id: "ntt_math_0265", subject: "math", category: "場合の数", level: 4, type: "input", question: "異なる9個から1個を選ぶ方法(組み合わせ)は何通りありますか?", answer: "9通り", steps: ["9!/(1!×8!) を計算する", "= 9通り"], explanation: "順序を区別しない「組み合わせ」は、まず順列(並べる場合の数)を求めてから、選んだ1個を並べ替える1!通りで割ることで求められます。" },
  { id: "ntt_math_0266", subject: "math", category: "一次方程式", level: 2, type: "input", question: "2x - 26 = -54 を解きなさい。xの値を答えなさい。", answer: "-14", steps: ["2x = -54 - (-26)", "2x = -28", "x = -28 ÷ 2 = -14"], explanation: "方程式を解くときは、xの項を左辺に、数だけの項を右辺に移項して整理します。「+26」を右辺に移項すると符号が反対の「-26」になります。最後に両辺をxの係数2で割ってxを求めます。" },
  { id: "ntt_math_0267", subject: "math", category: "速さ・時間・距離", level: 2, type: "input", question: "90kmの道のりを時速30kmで進むと何時間かかりますか?", answer: "3時間", steps: ["時間 = 距離 ÷ 速さ", "90 ÷ 30 = 3"], explanation: "「時間=距離÷速さ」という公式を使います。「距離=速さ×時間」の式を時間について解いた形です。" },
  { id: "ntt_math_0268", subject: "math", category: "確率", level: 3, type: "input", question: "赤玉6個、白玉8個が入った袋から1個取り出すとき、赤玉が出る確率を求めなさい。", answer: "3/7", steps: ["全体の玉の数: 6 + 8 = 14個", "確率 = 6/14 = 3/7"], explanation: "確率は「求める場合の数÷すべての場合の数」で計算します。袋の中の玉は全部で14個あり、そのうち赤玉は6個です。" },
  { id: "ntt_math_0269", subject: "math", category: "一次方程式", level: 2, type: "input", question: "4x + 12 = 60 を解きなさい。xの値を答えなさい。", answer: "12", steps: ["4x = 60 - (12)", "4x = 48", "x = 48 ÷ 4 = 12"], explanation: "方程式を解くときは、xの項を左辺に、数だけの項を右辺に移項して整理します。「+12」を右辺に移項すると符号が反対の「-12」になります。最後に両辺をxの係数4で割ってxを求めます。" },
  { id: "ntt_math_0270", subject: "math", category: "割合", level: 5, type: "input", question: "定価9300円の商品を10%値上げした後、さらにそこから10%値引きした。最終的な価格はいくらですか?", answer: "9207円", steps: ["値上げ後: 9300 × (100+10) ÷ 100 = 10230", "値引き後: 10230 × (100-10) ÷ 100 = 9207"], explanation: "割合の変化が2回続く問題では、1回ごとに順番に計算していきます。値上げ後の価格を先に求め、その新しい価格を基準にして値引きを計算する点に注意してください(最初の定価をもとに値引き額を計算するのではありません)。" },
  { id: "ntt_math_0271", subject: "math", category: "確率", level: 3, type: "input", question: "赤玉6個、白玉7個が入った袋から1個取り出すとき、赤玉が出る確率を求めなさい。", answer: "6/13", steps: ["全体の玉の数: 6 + 7 = 13個", "確率 = 6/13 = 6/13"], explanation: "確率は「求める場合の数÷すべての場合の数」で計算します。袋の中の玉は全部で13個あり、そのうち赤玉は6個です。" },
  { id: "ntt_math_0272", subject: "math", category: "図形", level: 3, type: "input", question: "縦6cm、横10cmの長方形の面積を求めなさい。", answer: "60cm²", steps: ["面積 = 縦 × 横", "6 × 10 = 60"], explanation: "長方形の面積は「縦×横」で求めます。" },
  { id: "ntt_math_0273", subject: "math", category: "図形と計量", level: 4, type: "choice", question: "sin30° の値を求めなさい。", choices: ["1/2", "0", "1", "√2/2"], answer: "1/2", explanation: "sin30°=1/2という三角比の基本値です。30°-60°-90°の直角三角形の辺の比(1:2:√3)から求められます。" },
  { id: "ntt_math_0274", subject: "math", category: "二次方程式", level: 3, type: "choice", question: "x² - 13x + 42 = 0 を解きなさい。", choices: ["x=6, 7", "x=7, 7", "x=6, 8", "x=-6, -7"], answer: "x=6, 7", steps: ["かけて42、足して13になる2数を探す → 6 と 7", "(x-(6))(x-(7)) = 0", "x = 6, 7"], explanation: "二次方程式は、左辺を(x-○)(x-△)の形に因数分解できれば、○と△が解になります。かけて42、足して13になる2つの数を探すと6と7が見つかります。" },
  { id: "ntt_math_0275", subject: "math", category: "平方根", level: 3, type: "input", question: "√169 の値を求めなさい。", answer: "13", steps: ["13 × 13 = 169", "よって √169 = 13"], explanation: "√169(ルート169)とは、2乗すると169になる正の数のことです。13を2乗すると13×13=169になるので、√169=13です。" },
  { id: "ntt_math_0276", subject: "math", category: "場合の数", level: 4, type: "input", question: "異なる5個から5個を選んで並べる方法(順列)は何通りありますか?", answer: "120通り", steps: ["5 × 4 × 3 × 2 × 1 = 120"], explanation: "順序を区別して並べる「順列」は、1番目に選べるものが5通り、2番目は残りの4通り、というように1つずつ減らしながらかけ合わせます。" },
  { id: "ntt_math_0277", subject: "math", category: "二次方程式", level: 3, type: "choice", question: "x² + 8x + 7 = 0 を解きなさい。", choices: ["x=-7, -1", "x=-6, -1", "x=-7, 0", "x=7, 1"], answer: "x=-7, -1", steps: ["かけて7、足して-8になる2数を探す → -7 と -1", "(x-(-7))(x-(-1)) = 0", "x = -7, -1"], explanation: "二次方程式は、左辺を(x-○)(x-△)の形に因数分解できれば、○と△が解になります。かけて7、足して-8になる2つの数を探すと-7と-1が見つかります。" },
  { id: "ntt_math_0278", subject: "math", category: "比例・反比例", level: 2, type: "input", question: "yはxに比例し、x=10のときy=80である。x=3のときのyの値を求めなさい。", answer: "24", steps: ["比例定数 k = 80 ÷ 10 = 8", "y = 8 × 3 = 24"], explanation: "yがxに比例するとき、y=k×xという式が成り立ち、kを比例定数といいます。まず与えられた条件からkを求め、そのkを使って求めたいyの値を計算します。" },
  { id: "ntt_math_0279", subject: "math", category: "損益算", level: 5, type: "input", question: "原価6150円の商品に30%の利益を見込んで定価をつけた。定価はいくらですか?", answer: "7995円", steps: ["利益額: 6150 × 30 ÷ 100 = 1845", "定価: 6150 + 1845 = 7995"], explanation: "「○%の利益を見込む」ということは、原価に原価の○%を上乗せするということです。定価は「原価×(100+○)/100」で求められます。" },
  { id: "ntt_math_0280", subject: "math", category: "割合", level: 5, type: "input", question: "定価2300円の商品を30%値上げした後、さらにそこから20%値引きした。最終的な価格はいくらですか?", answer: "2392円", steps: ["値上げ後: 2300 × (100+30) ÷ 100 = 2990", "値引き後: 2990 × (100-20) ÷ 100 = 2392"], explanation: "割合の変化が2回続く問題では、1回ごとに順番に計算していきます。値上げ後の価格を先に求め、その新しい価格を基準にして値引きを計算する点に注意してください(最初の定価をもとに値引き額を計算するのではありません)。" },
  { id: "ntt_math_0281", subject: "math", category: "四則演算", level: 1, type: "input", question: "5 + 36 ÷ 12 を計算しなさい。", answer: "8", steps: ["36 ÷ 12 = 3", "5 + 3 = 8"], explanation: "わり算はたし算より先に計算するというルールに従い、まず36÷12を計算してから5を足します。" },
  { id: "ntt_math_0282", subject: "math", category: "二次方程式", level: 3, type: "choice", question: "x² + 7x + 12 = 0 を解きなさい。", choices: ["x=-4, -3", "x=-3, -3", "x=-4, -2", "x=4, 3"], answer: "x=-4, -3", steps: ["かけて12、足して-7になる2数を探す → -4 と -3", "(x-(-4))(x-(-3)) = 0", "x = -4, -3"], explanation: "二次方程式は、左辺を(x-○)(x-△)の形に因数分解できれば、○と△が解になります。かけて12、足して-7になる2つの数を探すと-4と-3が見つかります。" },
  { id: "ntt_math_0283", subject: "math", category: "場合の数", level: 4, type: "input", question: "異なる4個から2個を選ぶ方法(組み合わせ)は何通りありますか?", answer: "6通り", steps: ["4!/(2!×2!) を計算する", "= 6通り"], explanation: "順序を区別しない「組み合わせ」は、まず順列(並べる場合の数)を求めてから、選んだ2個を並べ替える2!通りで割ることで求められます。" },
  { id: "ntt_math_0284", subject: "math", category: "比", level: 2, type: "input", question: "A:B = 8:9 で A=48 のとき、Bの値を求めなさい。", answer: "54", steps: ["48 ÷ 8 = 6倍", "9 × 6 = 54"], explanation: "比が等しいとき、A:B=8:9という関係はどれだけ数が大きくなっても保たれます。AがA=48になったのは、もとの比の8を何倍したかを考えると、B=9にも同じ倍率をかければ求められます。" },
  { id: "ntt_math_0285", subject: "math", category: "整数", level: 1, type: "input", question: "28と58の最小公倍数を求めなさい。", answer: "812", steps: ["28と58の最大公約数は2", "28 × 58 ÷ 2 = 812"], explanation: "最小公倍数とは、2つの数のどちらの倍数にもなっている整数のうち、最も小さいものです。最大公約数を使うと (最小公倍数)=(28×58)÷(最大公約数) で求められます。" },
  { id: "ntt_math_0286", subject: "math", category: "消費税", level: 2, type: "input", question: "税抜き9300円の商品に消費税8%がかかるとき、税込み価格はいくらですか?", answer: "10044円", steps: ["消費税額: 9300 × 8 ÷ 100 = 744", "税込み価格: 9300 + 744 = 10044"], explanation: "税込み価格は「税抜き価格+消費税額」で求めます。消費税額は税抜き価格に税率(%)をかけて100で割ることで計算できます。" },
  { id: "ntt_math_0287", subject: "math", category: "確率", level: 3, type: "input", question: "赤玉2個、白玉1個が入った袋から1個取り出すとき、赤玉が出る確率を求めなさい。", answer: "2/3", steps: ["全体の玉の数: 2 + 1 = 3個", "確率 = 2/3 = 2/3"], explanation: "確率は「求める場合の数÷すべての場合の数」で計算します。袋の中の玉は全部で3個あり、そのうち赤玉は2個です。" },
  { id: "ntt_math_0288", subject: "math", category: "金額計算", level: 1, type: "input", question: "150円の品物を買うのに5000円出しました。おつりはいくらですか?", answer: "4850円", steps: ["5000 - 150 = 4850"], explanation: "おつりは「支払った金額-品物の値段」で求めます。5000円出して150円の品物を買ったので、5000-150=4850円がおつりになります。" },
  { id: "ntt_math_0289", subject: "math", category: "仕事算", level: 5, type: "input", question: "ある作業をAさん1人で行うと10日、Bさん1人で行うと15日かかる。2人で一緒に行うと何日で終わりますか?", answer: "6日", steps: ["Aさんの1日の仕事量: 1/10、Bさんの1日の仕事量: 1/15", "2人合わせた1日の仕事量: 1/10 + 1/15 = 25/150", "かかる日数 = 1 ÷ (25/150) = 150/25 = 6日"], explanation: "仕事全体の量を1とすると、Aさんは1日に1/10、Bさんは1日に1/15の仕事をこなします。2人が一緒に働くと1日あたりの仕事量はその合計になるので、全体の1をその合計で割ると完成にかかる日数が求められます。" },
  { id: "ntt_math_0290", subject: "math", category: "速さ・時間・距離", level: 2, type: "input", question: "180kmの道のりを時速45kmで進むと何時間かかりますか?", answer: "4時間", steps: ["時間 = 距離 ÷ 速さ", "180 ÷ 45 = 4"], explanation: "「時間=距離÷速さ」という公式を使います。「距離=速さ×時間」の式を時間について解いた形です。" },
  { id: "ntt_math_0291", subject: "math", category: "損益算", level: 5, type: "input", question: "原価8550円の商品に20%の利益を見込んで定価をつけた。定価はいくらですか?", answer: "10260円", steps: ["利益額: 8550 × 20 ÷ 100 = 1710", "定価: 8550 + 1710 = 10260"], explanation: "「○%の利益を見込む」ということは、原価に原価の○%を上乗せするということです。定価は「原価×(100+○)/100」で求められます。" },
  { id: "ntt_math_0292", subject: "math", category: "確率", level: 3, type: "input", question: "赤玉1個、白玉3個が入った袋から1個取り出すとき、赤玉が出る確率を求めなさい。", answer: "1/4", steps: ["全体の玉の数: 1 + 3 = 4個", "確率 = 1/4 = 1/4"], explanation: "確率は「求める場合の数÷すべての場合の数」で計算します。袋の中の玉は全部で4個あり、そのうち赤玉は1個です。" },
  { id: "ntt_math_0293", subject: "math", category: "図形", level: 3, type: "input", question: "縦17cm、横18cmの長方形の周りの長さを求めなさい。", answer: "70cm", steps: ["周りの長さ = (縦 + 横) × 2", "(17 + 18) × 2 = 70"], explanation: "長方形の周りの長さは、縦と横をそれぞれ2辺ずつ持つので「(縦+横)×2」で求めます。" },
  { id: "ntt_math_0294", subject: "math", category: "整数", level: 1, type: "input", question: "6と36の最小公倍数を求めなさい。", answer: "36", steps: ["6と36の最大公約数は6", "6 × 36 ÷ 6 = 36"], explanation: "最小公倍数とは、2つの数のどちらの倍数にもなっている整数のうち、最も小さいものです。最大公約数を使うと (最小公倍数)=(6×36)÷(最大公約数) で求められます。" },
  { id: "ntt_math_0295", subject: "math", category: "分数", level: 1, type: "input", question: "1 + 6/7 を計算しなさい(答えは既約分数で)。", answer: "13/7", steps: ["分母を7にそろえる(通分)", "分子どうしを足す", "約分すると 13/7"], explanation: "分母の違う分数をたすときは、まず通分して分母をそろえる必要があります。1と7の最小公倍数7に通分してから分子どうしを足し、最後に約分すると13/7になります。" },
  { id: "ntt_math_0296", subject: "math", category: "速さ・時間・距離", level: 2, type: "input", question: "48kmの道のりを時速24kmで進むと何時間かかりますか?", answer: "2時間", steps: ["時間 = 距離 ÷ 速さ", "48 ÷ 24 = 2"], explanation: "「時間=距離÷速さ」という公式を使います。「距離=速さ×時間」の式を時間について解いた形です。" },
  { id: "ntt_math_0297", subject: "math", category: "分数", level: 1, type: "input", question: "7/6 × 4/3 を計算しなさい(答えは既約分数で)。", answer: "14/9", steps: ["分子どうし・分母どうしをかける", "約分すると 14/9"], explanation: "分数どうしのかけ算は、通分せずにそのまま分子は分子どうし、分母は分母どうしをかけます。かけた後に約分すると14/9になります。" },
  { id: "ntt_math_0298", subject: "math", category: "平均", level: 1, type: "input", question: "3個の数 40、50、54 の平均を求めなさい。", answer: "48", steps: ["40+50+54 = 144", "144 ÷ 3 = 48"], explanation: "平均とは、いくつかの数を均等にならしたときの値のことで、「合計÷個数」で求めます。まずすべての数を足し合わせ、その合計を個数で割ります。" },
  { id: "ntt_math_0299", subject: "math", category: "二次方程式", level: 3, type: "choice", question: "x² + 7x + 6 = 0 を解きなさい。", choices: ["x=-6, -1", "x=-5, -1", "x=-6, 0", "x=6, 1"], answer: "x=-6, -1", steps: ["かけて6、足して-7になる2数を探す → -6 と -1", "(x-(-6))(x-(-1)) = 0", "x = -6, -1"], explanation: "二次方程式は、左辺を(x-○)(x-△)の形に因数分解できれば、○と△が解になります。かけて6、足して-7になる2つの数を探すと-6と-1が見つかります。" },
  { id: "ntt_math_0300", subject: "math", category: "速さ・時間・距離", level: 5, type: "input", question: "56km離れた地点からAさんとBさんが同時に向かい合って出発した。Aさんは時速7km、Bさんは時速7kmで進むとき、2人が出会うのは何時間後ですか?", answer: "4時間後", steps: ["2人の速さの和: 7 + 7 = 14km/時", "出会うまでの時間: 56 ÷ 14 = 4時間"], explanation: "2人が向かい合って進むとき、2人の間の距離は「2人の速さの和」の速さで縮まっていきます。したがって、2人の速さを足したものを「合わせた速さ」として、通常の距離÷速さの計算で出会うまでの時間が求められます。" },
  { id: "ntt_math_0301", subject: "math", category: "速さ・時間・距離", level: 5, type: "input", question: "26km離れた地点からAさんとBさんが同時に向かい合って出発した。Aさんは時速8km、Bさんは時速5kmで進むとき、2人が出会うのは何時間後ですか?", answer: "2時間後", steps: ["2人の速さの和: 8 + 5 = 13km/時", "出会うまでの時間: 26 ÷ 13 = 2時間"], explanation: "2人が向かい合って進むとき、2人の間の距離は「2人の速さの和」の速さで縮まっていきます。したがって、2人の速さを足したものを「合わせた速さ」として、通常の距離÷速さの計算で出会うまでの時間が求められます。" },
  { id: "ntt_math_0302", subject: "math", category: "図形", level: 3, type: "input", question: "半径4cmの円の面積を求めなさい。円周率はπとすること。", answer: "16πcm²", steps: ["面積 = 半径 × 半径 × π", "4 × 4 × π = 16π"], explanation: "円の面積は「半径×半径×円周率」で求めます。円周率はπのまま計算してよいので、数値の掛け算だけ行います。" }
];
